import { Tooltip, TooltipContent, TooltipTrigger } from "@superset/ui/tooltip";
import { LuPlus } from "react-icons/lu";
import { useV2UserPreferences } from "renderer/hooks/useV2UserPreferences";
import { useDashboardSidebarState } from "renderer/routes/_authenticated/hooks/useDashboardSidebarState";
import type { SessionSectionFlag } from "renderer/routes/_authenticated/providers/CollectionsProvider/dashboardSidebarLocal";
import { useOpenNewSessionModal } from "renderer/stores/new-workspace-modal";
import type { DashboardSidebarWorkspace } from "../../types";
import { DashboardSidebarStateSection } from "../DashboardSidebarStateSection";
import { DashboardSidebarWorkspaceItem } from "../DashboardSidebarWorkspaceItem";
import { DashboardSidebarSessionsContextMenu } from "./components/DashboardSidebarSessionsContextMenu";

interface DashboardSidebarSessionsSectionProps {
	sessionWorkspaces: DashboardSidebarWorkspace[];
	/** (SESSION-LIFECYCLE) Rows for the Snoozed Sessions subsection, soonest
	 * wake first. */
	snoozedSessionWorkspaces?: DashboardSidebarWorkspace[];
	/** (SESSION-LIFECYCLE) Rows for the Archived Sessions subsection, most
	 * recently archived first. */
	archivedSessionWorkspaces?: DashboardSidebarWorkspace[];
	isCollapsed?: boolean;
	/** The workspaces-list collapse toggle hides rows; the header stays. */
	rowsHidden?: boolean;
	workspaceShortcutLabels?: Map<string, string>;
	onWorkspaceHover: (workspaceId: string) => void | Promise<void>;
}

/**
 * Top-level "Sessions" section, rendered above the Projects header. The
 * header (and its "+", which opens the create surface with "No project"
 * preselected) always renders in expanded mode — like the Projects header —
 * so sessions stay discoverable at zero. Collapsed rail renders a plain icon
 * stack with a trailing divider, matching the Pinned section.
 *
 * (SESSION-LIFECYCLE) A snoozed or archived session leaves the active list and
 * moves into the matching subsection below, which the header's right-click menu
 * reveals or hides. Sessions never reach the Kanban board: every card is bound
 * to a sidebar project, and a session has none.
 */
export function DashboardSidebarSessionsSection({
	sessionWorkspaces,
	snoozedSessionWorkspaces = [],
	archivedSessionWorkspaces = [],
	isCollapsed = false,
	rowsHidden = false,
	workspaceShortcutLabels,
	onWorkspaceHover,
}: DashboardSidebarSessionsSectionProps) {
	const openNewSessionModal = useOpenNewSessionModal();
	const { preferences, setSessionSectionFlag, toggleSessionSectionFlag } =
		useV2UserPreferences();
	const { unsnoozeAllInProject, unarchiveWorkspaces } =
		useDashboardSidebarState();

	if (isCollapsed) {
		if (sessionWorkspaces.length === 0) return null;
		return (
			<div className="flex flex-col gap-0.5 py-1">
				{sessionWorkspaces.map((workspace) => (
					<DashboardSidebarWorkspaceItem
						key={workspace.id}
						workspace={workspace}
						isCollapsed
						isInSection={false}
						onHoverCardOpen={() => onWorkspaceHover(workspace.id)}
					/>
				))}
				<div className="mx-3 mt-1 border-b border-border" />
			</div>
		);
	}

	// One config entry per subsection keeps the two reveal blocks in sync, the
	// same way DashboardSidebarProjectSection drives its own state sections.
	const stateSections: Array<{
		variant: "snoozed" | "archived";
		title: string;
		show: boolean;
		workspaces: DashboardSidebarWorkspace[];
		collapsed: boolean;
		collapsedFlag: SessionSectionFlag;
		showFlag: SessionSectionFlag;
		onRestoreAll: () => void;
	}> = [
		{
			variant: "snoozed",
			title: "Snoozed Sessions",
			show: preferences.showSnoozedSessions,
			workspaces: snoozedSessionWorkspaces,
			collapsed: preferences.snoozedSessionsCollapsed,
			collapsedFlag: "snoozedSessionsCollapsed",
			showFlag: "showSnoozedSessions",
			// Sessions hold a null projectId, which is exactly the lane this
			// bulk-unsnooze filters on.
			onRestoreAll: () => unsnoozeAllInProject(null),
		},
		{
			variant: "archived",
			title: "Archived Sessions",
			show: preferences.showArchivedSessions,
			workspaces: archivedSessionWorkspaces,
			collapsed: preferences.archivedSessionsCollapsed,
			collapsedFlag: "archivedSessionsCollapsed",
			showFlag: "showArchivedSessions",
			onRestoreAll: () =>
				unarchiveWorkspaces(
					archivedSessionWorkspaces.map((workspace) => workspace.id),
				),
		},
	];

	return (
		<div className="pb-1">
			<DashboardSidebarSessionsContextMenu
				showSnoozed={preferences.showSnoozedSessions}
				showArchived={preferences.showArchivedSessions}
				onToggleSnoozed={() => toggleSessionSectionFlag("showSnoozedSessions")}
				onToggleArchived={() =>
					toggleSessionSectionFlag("showArchivedSessions")
				}
			>
				{/* Header styled to match the Projects header below it. */}
				<div className="flex min-h-8 w-full shrink-0 items-center gap-1.5 py-1.5 pl-4 pr-2 text-[10px] font-semibold uppercase tracking-[0.075em] text-muted-foreground">
					<span className="min-w-0 truncate text-left">Sessions</span>
					<div className="min-w-0 flex-1" />
					<Tooltip delayDuration={700}>
						<TooltipTrigger asChild>
							<button
								type="button"
								aria-label="New session"
								onClick={openNewSessionModal}
								className="flex size-6 shrink-0 items-center justify-center rounded-md text-muted-foreground transition-colors hover:bg-fill-hover hover:text-foreground"
							>
								<LuPlus className="size-3.5" />
							</button>
						</TooltipTrigger>
						<TooltipContent side="bottom">New session</TooltipContent>
					</Tooltip>
				</div>
			</DashboardSidebarSessionsContextMenu>
			{!rowsHidden &&
				sessionWorkspaces.map((workspace) => (
					<DashboardSidebarWorkspaceItem
						key={workspace.id}
						workspace={workspace}
						shortcutLabel={workspaceShortcutLabels?.get(workspace.id)}
						onHoverCardOpen={() => onWorkspaceHover(workspace.id)}
					/>
				))}
			{!rowsHidden &&
				stateSections
					.filter((section) => section.show)
					.map((section) => (
						<DashboardSidebarStateSection
							key={section.variant}
							variant={section.variant}
							title={section.title}
							workspaces={section.workspaces}
							collapsed={section.collapsed}
							onToggleCollapsed={() =>
								toggleSessionSectionFlag(section.collapsedFlag)
							}
							onHide={() => setSessionSectionFlag(section.showFlag, false)}
							onRestoreAll={section.onRestoreAll}
							onWorkspaceHover={onWorkspaceHover}
						/>
					))}
		</div>
	);
}

/**
 * (SESSION-LIFECYCLE) Every Kanban card is bound to a branch inside a sidebar
 * project — the board's columns, promote-to-branch drag and completed-context
 * label all assume a repo behind the card. A "session" is project-less by
 * definition, so it is excluded here rather than relying on `Set.has(null)`
 * happening to be false: sessions must never seed, heal into, or render as a
 * card. A workspace whose project has been removed from the sidebar is
 * excluded for the same reason it is hidden in the sidebar.
 */
export function isKanbanEligibleWorkspace(
	workspace: { projectId: string | null },
	sidebarProjectIds: ReadonlySet<string>,
): boolean {
	if (workspace.projectId === null) return false;
	return sidebarProjectIds.has(workspace.projectId);
}

	return (
		"plain" in value &&
		"shift" in value &&
		"meta" in value &&
		"metaShift" in value
	);
}

export const v2UserPreferencesSchema = z.object({
	id: z.literal("preferences"),
	fileLinks: linkTierMapSchema.default(DEFAULT_LINK_TIER_MAP),
	urlLinks: linkTierMapSchema.default(DEFAULT_URL_LINKS),
	sidebarFileLinks: linkTierMapSchema.default(DEFAULT_SIDEBAR_FILE_LINKS),
	portOpenAction: linkActionSchema.default(DEFAULT_PORT_OPEN_ACTION),
	terminalPresetsInitialized: z.boolean().default(false),
	rightSidebarOpen: z.boolean().default(true),
	rightSidebarTab: z.enum(["changes", "files"]).default("changes"),
	rightSidebarWidth: z.number().default(340),
	deleteLocalBranch: z.boolean().default(false),
	showPresetsBar: z.boolean().default(true),
	/**
	 * (SESSION-LIFECYCLE) Reveal/collapse flags for the top-level Snoozed
	 * Sessions / Archived Sessions subsections. Sessions have no project row, so
	 * the per-project equivalents on `dashboardSidebarProjectSchema` have nowhere
	 * to live — these ride the fixed-size preferences singleton instead (bounded:
	 * four booleans, no per-entity cardinality).
	 */
	showSnoozedSessions: z.boolean().default(false),
	showArchivedSessions: z.boolean().default(false),
	snoozedSessionsCollapsed: z.boolean().default(false),
	archivedSessionsCollapsed: z.boolean().default(false),
	// Built-in (synthetic, app-shipped) presets the user hid from the preset
	// bar. Synthetic presets have no v2TerminalPresets row, so visibility can't
	// live on the row's pinnedToBar like user presets. Pruned against
	// KNOWN_BUILTIN_PRESET_IDS at heal time so retired ids can't persist.
	hiddenBuiltinPresetIds: z.array(z.string()).default([]),
});

// The fixed set of built-in preset ids. Consumers derive their id constants
// from this list (compile-checked via `satisfies`) so the heal-time pruning
// below can never drop an id that is still in use.
export const KNOWN_BUILTIN_PRESET_IDS = ["superset-cli"] as const;

export type V2UserPreferencesRow = z.infer<typeof v2UserPreferencesSchema>;

export const V2_USER_PREFERENCES_ID = "preferences" as const;

export const DEFAULT_V2_USER_PREFERENCES: V2UserPreferencesRow = {
	id: V2_USER_PREFERENCES_ID,
	fileLinks: DEFAULT_LINK_TIER_MAP,
	urlLinks: DEFAULT_URL_LINKS,
	sidebarFileLinks: DEFAULT_SIDEBAR_FILE_LINKS,
	portOpenAction: DEFAULT_PORT_OPEN_ACTION,
	terminalPresetsInitialized: false,
	rightSidebarOpen: true,
	rightSidebarTab: "changes",
	rightSidebarWidth: 340,
	deleteLocalBranch: false,
	showPresetsBar: true,
	showSnoozedSessions: false,
	showArchivedSessions: false,
	snoozedSessionsCollapsed: false,
	archivedSessionsCollapsed: false,
	hiddenBuiltinPresetIds: [],
};

/**
 * Heal a stored workspaceLocalState row against current defaults. Identity
 * fields (workspaceId, projectId, paneLayout, createdAt) pass through from
 * the stored row — they have no synthesizable default. Optional fields with
 * intrinsic defaults get filled at both the top level and inside sidebarState.
 */
export function healWorkspaceLocalState(raw: unknown): WorkspaceLocalStateRow {
	const r = (
		raw && typeof raw === "object" ? raw : {}
	) as Partial<WorkspaceLocalStateRow>;
	const sidebar = (
		r.sidebarState && typeof r.sidebarState === "object" ? r.sidebarState : {}
	) as Partial<WorkspaceLocalStateRow["sidebarState"]>;
	return {

