1	import { z } from "zod";
2	
3	export const companionLifecycleFields = {
4		companionLifecycleEventId: z
5			.string()
6			.regex(/^[A-Za-z0-9_-]{22}$/)
7			.optional(),
8		companionLifecycleOutcome: z
9			.enum(["progress", "ready", "failed", "hold", "session-end"])
10			.optional(),
11	};
12	
13	export interface CompanionLifecycleEvent {
14		eventId: string;
15		outcome: "progress" | "ready" | "failed" | "hold" | "session-end";
16		eventType: string;
17		hostTerminalId: string;
18		hostWorkspaceId: string;
19		agentSessionId: string | null;
20		occurredAtMs: number;
21	}
22	
23	export interface CompanionLifecycleSink {
24		record(input: CompanionLifecycleEvent): void;
25	}
26	
27	let sink: CompanionLifecycleSink | null = null;
28	
29	export function setCompanionLifecycleSink(
30		next: CompanionLifecycleSink | null,
31	): void {
32		if (next !== null && sink !== null) {
33			throw new Error(
34				"[companion-lifecycle] a lifecycle sink is already registered; unregister it before installing another",
35			);
36		}
37		sink = next;
38	}
