57		hostTerminalId: string;
58		armedAtMs: number;
59		kind: LifecycleAlertKind;
60	}): string {
61		return createHash("sha256")
62			.update("sc/v2 lifecycle alert\0", "utf8")
63			.update(input.kind, "utf8")
64			.update("\0", "utf8")
65			.update(input.hostTerminalId, "utf8")
66			.update("\0", "utf8")
67			.update(String(input.armedAtMs), "utf8")
68			.digest("base64url")
69			.slice(0, 22);
70	}
