72	/**
73	 * Lifecycle delivery state is intentionally process-local. The validated hook
74	 * stream and the host DB remain the lifecycle source of truth; this bounded map
75	 * only holds informational alerts while presence or sidebar curation delays
76	 * delivery. A host-service restart can lose an unsent held alert. Durable
77	 * delivery would require an explicitly approved database schema change.
78	 */
79	export function createLifecycleAlertManager(
80		deps: LifecycleAlertManagerDeps,
81	): LifecycleAlertManager {
82		const now = deps.now ?? (() => Date.now());
83		const alerts = new Map<string, HeldAlert>();
84		let stopped = false;
85		let timer: NodeJS.Timeout | null = null;
86	
87		function trimOldest<T>(map: Map<string, T>): void {
88			while (map.size > MAX_STATE_ENTRIES) {
89				const oldest = map.keys().next();
90				if (oldest.done) return;
91				map.delete(oldest.value);
92			}
93		}
94	
95		function prune(nowMs: number): void {
96			for (const [alertId, alert] of alerts) {
97				if (alert.expiresAtMs <= nowMs) alerts.delete(alertId);
98			}
99			trimOldest(alerts);
100		}
101	
102		function heldAlerts(): HeldAlert[] {
103			return [...alerts.values()].filter((alert) => alert.state === "held");
104		}
105	
106		function scheduleSweep(): void {
107			if (timer !== null || stopped || heldAlerts().length === 0) return;
108			timer = setTimeout(() => {
109				timer = null;
110				void sweep();
111			}, SWEEP_MS);
112			timer.unref?.();
113		}
114	
115		async function send(alert: HeldAlert): Promise<void> {
116			if (stopped) return;
117			const nowMs = now();
118			if (alert.expiresAtMs <= nowMs) {
119				alerts.delete(alert.alertId);
120				return;
121			}
122			if (deps.presence.present(nowMs).present) return;
123			if (deps.isCuratedOff(alert.hostWorkspaceId)) return;
124			alerts.set(alert.alertId, { ...alert, state: "sent", updatedAtMs: nowMs });
125			try {
126				await deps.push.sendLifecycleAlert({
127					alertId: alert.alertId,
128					workspaceId: alert.workspaceHandle,
129					kind: alert.kind,
130					expiresAtMs: alert.expiresAtMs,
131				});
132			} catch (error) {
133				deps.logger.error("could not send lifecycle alert", {
134					alertId: alert.alertId,
135					kind: alert.kind,
136					error,
137				});
138			}
139		}
140	
141		async function sweep(): Promise<void> {
142			prune(now());
143			for (const alert of heldAlerts()) await send(alert);
144			scheduleSweep();
145		}
146	
147		function mint(
148			input: CompanionLifecycleEvent,
149			cycleStartedAtMs: number,
150			kind: LifecycleAlertKind,
151		): void {
152			const alertId = lifecycleAlertId({
153				hostTerminalId: input.hostTerminalId,
154				armedAtMs: cycleStartedAtMs,
155				kind,
156			});
157			if (alerts.has(alertId)) return;
158			const nowMs = now();
159			const alert: HeldAlert = {
160				alertId,
161				kind,
162				hostWorkspaceId: input.hostWorkspaceId,
163				workspaceHandle: deps.workspaceHandle(input.hostWorkspaceId),
164				expiresAtMs: input.occurredAtMs + ALERT_TTL_MS,
165				state: "held",
166				updatedAtMs: nowMs,
167			};
168			alerts.set(alertId, alert);
169			prune(nowMs);
170			void send(alert);
171			scheduleSweep();
172		}
173	
174		return {
175			record(input) {
176				if (stopped) return;
177				prune(now());
178				if (input.outcome !== "ready" && input.outcome !== "failed") return;
179	
180				// DB source of truth: the router captures these fields from the persisted
181				// terminal binding before recordEvent replaces them. Only a terminal event
182				// following real work can produce an alert. Repeated Stop/Failed events see
183				// the previous terminal event and are therefore silent. PermissionRequest is
184				// intentionally absent: answering a prompt and ending the turn must not be
185				// reported as fresh completed work.
186				if (
187					input.previousEventAtMs === null ||
188					(input.previousEventType !== "Start" &&
189						input.previousEventType !== "SubagentActive" &&
190						input.previousEventType !== "BackgroundRunning")
191				)
192					return;
193	
194				mint(
195					input,
196					input.previousEventAtMs,
197					input.outcome === "failed" ? "e" : "g",
198				);
199			},
200			stop() {
201				stopped = true;
202				if (timer !== null) clearTimeout(timer);
203				timer = null;
204				alerts.clear();
205			},
206		};
207	}
