// Release signing lives OUTSIDE this repo, beside the FCM and Cloudflare secrets.
// Override with -PsigningPropertiesFile=... or SUPERSET_COMPANION_SIGNING.
val signingPropertiesPath: String =
    (findProperty("signingPropertiesFile") as String?)
        ?: System.getenv("SUPERSET_COMPANION_SIGNING")
        ?: "${System.getProperty("user.home")}/.superset/companion/keystore/signing.properties"

val signingProperties: Properties? = file(signingPropertiesPath)
    .takeIf { it.isFile }
    ?.let { f -> Properties().apply { f.inputStream().use { load(it) } } }

android {
    namespace = "family.khaira.supersetcompanion"
    compileSdk = 37

    defaultConfig {
        // MUST be identical to app-watch. The Wear Data Layer silently delivers
        // nothing between two apps whose applicationId or signing key differ —
        // no error, no callback, just silence.
        applicationId = "family.khaira.supersetcompanion"
        minSdk = 33
        targetSdk = 37
        versionCode = 1
        versionName = "0.1.0"
        testInstrumentationRunner = "androidx.test.runner.AndroidJUnitRunner"
    }

    signingConfigs {
        if (signingProperties != null) {
            create("release") {
                storeFile = file(signingProperties.getProperty("storeFile"))
                storePassword = signingProperties.getProperty("storePassword")
                keyAlias = signingProperties.getProperty("keyAlias")
                keyPassword = signingProperties.getProperty("keyPassword")
            }
        }
    }

    buildTypes {
        release {
            isMinifyEnabled = true
            isShrinkResources = true
            proguardFiles(getDefaultProguardFile("proguard-android-optimize.txt"), "proguard-rules.pro")
            signingConfig = signingConfigs.findByName("release")
                ?: throw GradleException(
                    "Release signing is not configured: $signingPropertiesPath is missing. " +
                        "app-phone and app-watch must be signed with the SAME key or the Data Layer " +
                        "silently fails. Generate it or point -PsigningPropertiesFile at it."
                )
        }
    }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }

    buildFeatures {
        compose = true
        buildConfig = true
    }

    testOptions {
        unitTests {
            // `android.util.Log` throws "not mocked" by default, which would force the
            // logging out of any class a JVM test touches. The registration path is the
            // one place where a silent failure is the bug being fixed, so its logging
            // stays and the stubs return defaults instead of throwing. Nothing under test
            // asserts on an android.* return value; anything that needs real framework
            // behaviour belongs in androidTest.
            isReturnDefaultValues = true
        }
    }
}

kotlin {
