package family.khaira.supersetcompanion.wear.notify

import android.Manifest
import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.content.Context
import android.content.Intent
import android.content.pm.PackageManager
import android.util.Log
import androidx.core.app.NotificationCompat
import androidx.core.app.NotificationManagerCompat
import androidx.core.content.ContextCompat
import family.khaira.supersetcompanion.core.wear.WatchLifecycleAlert
import family.khaira.supersetcompanion.wear.MainActivity
import family.khaira.supersetcompanion.wear.R

private const val TAG = "CompanionLifecycle"

/**
 * (LIFECYCLE-ALERT) The wrist's own alert for an agent that finished or failed.
 *
 * Deliberately not [QuestionNotifier]: a question notification promises an answer screen
 * behind the tap, and these have no answer. Nothing here goes near
 * [family.khaira.supersetcompanion.wear.state.QuestionStore] either — a lifecycle alert
 * must not displace a question the user is part-way through answering, and the store is
 * the thing that would displace it.
 *
 * Tapping opens the app at home. That is the whole interaction: the watch has no route to
 * the desktop of its own, and there is nothing here to confirm.
 */
object LifecycleNotifier {

    /** @return false when notifications are off, so the caller can surface that. */
    fun notify(context: Context, alert: WatchLifecycleAlert): Boolean {
        val presentation = LifecycleAlertPresentation.forKind(alert.kind)
        val manager = NotificationManagerCompat.from(context)
        // Two different "off"s, and both are silent from the wrist: the runtime permission
        // was never granted, or notifications are disabled for the app or its channel.
        // The permission check is inline rather than behind a helper because it is also
        // what makes `NotificationManagerCompat.notify` — which is annotated
        // @RequiresPermission — safe rather than a SecurityException waiting for a user
        // who said no, and lint only follows the check when it sits in this method.
        val granted = ContextCompat.checkSelfPermission(
            context,
            Manifest.permission.POST_NOTIFICATIONS,
        ) == PackageManager.PERMISSION_GRANTED
        if (!granted) {
            Log.e(
                TAG,
                "POST_NOTIFICATIONS is not granted — lifecycle alert ${alert.eventId} " +
                    "will not show",
            )
            return false
        }
        if (!manager.areNotificationsEnabled()) {
            Log.e(
                TAG,
                "notifications are disabled for this app — lifecycle alert ${alert.eventId} " +
                    "will not show",
            )
            return false
        }
        ensureChannel(context, presentation)

        val notificationId = LifecycleAlertPresentation.notificationId(alert.eventId)

        // No EXTRA_QUESTION_ID: MainActivity reads that extra to load a question, and an
        // alert that is not about a question must not send it looking for one.
        val open = Intent(context, MainActivity::class.java).apply {
            action = Intent.ACTION_MAIN
            flags = Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TOP
        }
        val pending = PendingIntent.getActivity(
            context,
            notificationId,
            open,
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE,
        )

        val notification = NotificationCompat.Builder(context, presentation.channelId)
            .setSmallIcon(R.drawable.ic_launcher_foreground)
            .setContentTitle(presentation.title)
            .setContentText(presentation.text)
            .setContentIntent(pending)
            .setCategory(
                if (presentation.vibrates) {
                    NotificationCompat.CATEGORY_ERROR
                } else {
                    NotificationCompat.CATEGORY_STATUS
                },
            )
            .setPriority(
                if (presentation.vibrates) {
                    NotificationCompat.PRIORITY_HIGH
                } else {
                    NotificationCompat.PRIORITY_DEFAULT
                },
            )
            .setAutoCancel(true)
            // The phone alerted once for this event and its notification is localOnly, so
            // this is the wrist's only copy; alerting again on an update would double it.
            .setOnlyAlertOnce(true)
            .build()

        manager.notify(notificationId, notification)
        return true
    }

    private fun ensureChannel(context: Context, presentation: LifecycleAlertText) {
        val manager = context.getSystemService(NotificationManager::class.java)
        if (manager.getNotificationChannel(presentation.channelId) != null) return
        val channel = NotificationChannel(
            presentation.channelId,
            presentation.channelName,
            if (presentation.vibrates) {
                NotificationManager.IMPORTANCE_HIGH
            } else {
                NotificationManager.IMPORTANCE_DEFAULT
            },
        ).apply {
            description = presentation.channelDescription
            enableVibration(presentation.vibrates)
            setShowBadge(false)
        }
        manager.createNotificationChannel(channel)
    }
}

