102				unknownTerminalReports.clear();
103			}
104			unknownTerminalReports.set(detail.terminalId, {
105				count: 1,
106				lastReportedAt: Date.now(),
107			});
108			console.error(
109				"[notifications] hook for a terminal with no session row",
110				detail,
111			);
112			return;
113		}
