package family.khaira.supersetcompanion.core.protocol

import family.khaira.supersetcompanion.core.ProtocolException

/** `k` in a lifecycle push payload (PROTOCOL.md §13.4). */
enum class LifecycleKind(val wire: String) {
    /** An agent finished and its work is waiting to be reviewed. Nothing is blocked. */
    READY("g"),

    /** An agent stopped on an error. Nothing is blocked either; nothing can proceed. */
    ERROR("e"),
    ;

    companion object {
        fun fromWire(raw: String): LifecycleKind? = entries.firstOrNull { it.wire == raw }
    }
}

/**
 * A lifecycle alert delivered as an FCM data-only message (PROTOCOL.md §13.4).
 *
 * These are **not** questions. A question blocks an agent and can be answered from the
 * phone or the wrist; a lifecycle alert only says that something changed state, so every
 * surface it reaches is read-only and opens the app rather than offering an answer.
 *
 * > **The §13.1 hard constraint applies unchanged: no workspace name, no branch name, no
 * > project name, no file path, no agent output, and no free text of any kind.** Google
 * > is not in the trust boundary and a lifecycle alert does not get an exemption because
 * > its text would have been short. The wording the user sees is a fixed local string.
 *
 * The payload is a **separate closed key set under `v` = [VERSION]**, deliberately not an
 * extra `k` inside v1. A build that predates lifecycle alerts stops at the version check
 * in [PushData.parse] — before its own closed-key check — and returns `null`, so an old
 * phone ignores these silently instead of refusing them as malformed. That ordering is
 * the whole backward-safety story and is pinned by a test.
 *
 * Like a question push it carries **nothing displayable**: [eventId] and [workspaceId]
 * are opaque, and the client renders fixed wording. It never invents text and it never
 * fetches text to put in a lifecycle alert.
 */
class LifecyclePushData private constructor(
    val kind: LifecycleKind,
    /**
     * `i` — the bridge's alert id: one per lifecycle alert, minted from the armed work
     * cycle that ended and the kind it ended in. It is the identity of the alert
     * everywhere, on the wire (`collapse_key`) and on both clients (the dedupe window and
     * the notification identity).
     */
    val eventId: String,
    val workspaceId: String,
    val expiresAtMs: Long,
) {
    fun isExpired(nowMs: Long): Boolean = nowMs >= expiresAtMs

    override fun toString(): String =
        "LifecyclePushData(kind=${kind.wire}, eventId=$eventId, workspaceId=$workspaceId)"

    companion object {
        /** The payload version that carries lifecycle alerts. v1 is questions only. */
        const val VERSION = "2"

        private const val LABEL = "lifecycle payload"
        private val KEYS = setOf("v", "k", "i", "w", "x")

        /**
         * @return `null` when `v` is not [VERSION] — this parser owns exactly one version
         *   and says nothing about the others; [CompanionPush.parse] dispatches. Anything
         *   else malformed is a hard error, because it means either a bridge bug or an
         *   attempt to smuggle content through Google.
         */
        fun parse(data: Map<String, String>): LifecyclePushData? {
            if (PushEnvelope.version(data) != VERSION) return null
            PushEnvelope.requireClosedAndOpaque(data, KEYS, LABEL, "§13.4")

            val kind =
                LifecycleKind.fromWire(required(data, "k"))
                    ?: throw ProtocolException("lifecycle payload 'k' is not a known kind")
            val expiry =
                required(data, "x").toLongOrNull()
                    ?: throw ProtocolException("lifecycle payload 'x' is not a number")

            return LifecyclePushData(
                kind = kind,
                eventId = Ids.requireOpaque16(required(data, "i"), "lifecycle.i"),
                workspaceId = Ids.requireOpaque16(required(data, "w"), "lifecycle.w"),
                expiresAtMs = expiry,
            )
        }

        private fun required(data: Map<String, String>, key: String): String =
            PushEnvelope.required(data, key, LABEL)
    }
}

/**
 * What arrived over FCM, once `v` has decided which closed key set applies.
 *
 * Version dispatch happens here and nowhere else, so adding a version can never loosen
 * the validation of an existing one: each parser still refuses every key it does not own.
 */
sealed interface CompanionPush {

    /** A question is pending, or one was retracted. The answerable path (§13.1). */
    data class Blocked(val data: PushData) : CompanionPush

    /** An agent finished or failed. Read-only on every surface (§13.4). */
    data class Lifecycle(val data: LifecyclePushData) : CompanionPush

    companion object {
        /**
         * @return `null` for a payload version this build does not implement. That is the
         *   forward-compatibility hinge in the other direction: a newer bridge can add a
         *   `v` and this build ignores it instead of guessing what it meant.
         */
        fun parse(data: Map<String, String>): CompanionPush? =
            when (PushEnvelope.version(data)) {
                PushData.VERSION -> PushData.parse(data)?.let { Blocked(it) }
                LifecyclePushData.VERSION -> LifecyclePushData.parse(data)?.let { Lifecycle(it) }
                else -> null
            }
    }
}

package family.khaira.supersetcompanion.core.protocol

import family.khaira.supersetcompanion.core.ProtocolException

/**
 * The envelope rules every FCM payload version shares: a closed key set, and values that
 * no natural-language string can satisfy.
 *
 * Shared between [PushData] (§13.1) and [LifecyclePushData] (§13.4) deliberately. These
 * are the checks that catch a text leak, and a leak does not announce which version it
 * arrived on — a second copy of them is a second chance to weaken one. Each version still
 * owns its own key set, its own kinds and its own field parsing; only the envelope is
 * common, and every message still names the version that refused the payload.
 */
internal object PushEnvelope {

    private val SAFE_VALUE = Regex("^[A-Za-z0-9_-]{1,43}$")

    /** @throws ProtocolException when there is no `v` at all, which is a bridge bug. */
    fun version(data: Map<String, String>): String =
        data["v"] ?: throw ProtocolException("push payload has no 'v'")

    /**
     * @param keys everything this version is allowed to carry. Anything else is refused.
     * @param label how the version names itself in an error, e.g. `"lifecycle payload"`.
     * @param section the PROTOCOL.md section that closes [keys], quoted in the error.
     */
    fun requireClosedAndOpaque(
        data: Map<String, String>,
        keys: Set<String>,
        label: String,
        section: String,
    ) {
        val unexpected = data.keys - keys
        if (unexpected.isNotEmpty()) {
            throw ProtocolException(
                "$label carries unexpected key(s) $unexpected — the key set is closed by " +
                    "PROTOCOL.md $section and an addition is how a text leak would arrive",
            )
        }
        for ((key, value) in data) {
            if (!SAFE_VALUE.matches(value)) {
                throw ProtocolException(
                    "$label key '$key' does not match the opaque-value pattern; " +
                        "no natural-language string can, so this is a leak or a bug",
                )
            }
        }
    }

    fun required(data: Map<String, String>, key: String, label: String): String =
        data[key] ?: throw ProtocolException("$label has no '$key'")
}

package family.khaira.supersetcompanion.core.protocol

import family.khaira.supersetcompanion.core.ProtocolException

/** `k` in the push payload. */
enum class PushKind(val wire: String) {
    /** A question is pending and nobody has dealt with it. */
    QUESTION("q"),

    /** Retraction — the question resolved somewhere. Cancel the notification. */
    RETRACT("r"),
    ;

    companion object {
        fun fromWire(raw: String): PushKind? = entries.firstOrNull { it.wire == raw }
    }
}

/**
 * An FCM data-only message (PROTOCOL.md §13.1).
 *
 * > **No question text, no option text, no workspace name, no branch name, no project
 * > name, no file path, and no free text of any kind may ever appear in an FCM message.**
 *
 * Google is not in the trust boundary. The bridge asserts that at runtime; this class
 * asserts it again on arrival, because a client that quietly accepted an extra key would
 * make a future leak invisible. Every value must match `^[A-Za-z0-9_-]{1,43}$`, which no
 * natural-language string can satisfy.
 *
 * Consequently a push carries **nothing displayable**. The client fetches `/v1/question`
 * over the sealed channel and only then renders a notification; if it cannot fetch —
 * offline, locked, revoked — it shows a contentless "an agent needs you". It never
 * invents text.
 */
class PushData private constructor(
    val kind: PushKind,
    val questionId: String,
    val workspaceId: String,
    val questionCount: Int,
    val expiresAtMs: Long,
) {
    fun isExpired(nowMs: Long): Boolean = nowMs >= expiresAtMs

    override fun toString(): String =
        "PushData(kind=${kind.wire}, questionId=$questionId, workspaceId=$workspaceId, n=$questionCount)"

    companion object {
        /**
         * The question payload version. Lifecycle alerts are a separate closed key set
         * under [LifecyclePushData.VERSION]; this parser owns v1 and refuses everything
         * that is not exactly v1's shape.
         */
        const val VERSION = "1"

        private const val LABEL = "push payload"
        private val KEYS = setOf("v", "k", "i", "w", "n", "x")

        /**
         * @return `null` when `v` is a payload version this build does not implement —
         *   the caller shows the contentless notification and moves on, which is the
         *   documented degradation. Anything else malformed is a hard error, because it
         *   means either a bridge bug or an attempt to smuggle content through Google.
         */
        fun parse(data: Map<String, String>): PushData? {
            if (PushEnvelope.version(data) != VERSION) return null
            PushEnvelope.requireClosedAndOpaque(data, KEYS, LABEL, "§13.1")

            val kind =
                PushKind.fromWire(required(data, "k"))
                    ?: throw ProtocolException("push payload 'k' is not a known kind")
            val count =
                required(data, "n").toIntOrNull()
                    ?: throw ProtocolException("push payload 'n' is not a number")
            val expiry =
                required(data, "x").toLongOrNull()
                    ?: throw ProtocolException("push payload 'x' is not a number")

            return PushData(
                kind = kind,
                questionId = Ids.requireOpaque16(required(data, "i"), "push.i"),
                workspaceId = Ids.requireOpaque16(required(data, "w"), "push.w"),
                questionCount = count,
                expiresAtMs = expiry,
            )
        }

        private fun required(data: Map<String, String>, key: String): String =
            PushEnvelope.required(data, key, LABEL)
    }
}

package family.khaira.supersetcompanion.push

import android.util.Log
import com.google.firebase.messaging.FirebaseMessagingService
import com.google.firebase.messaging.RemoteMessage
import family.khaira.supersetcompanion.core.ProtocolException
import family.khaira.supersetcompanion.core.protocol.CompanionPush
import family.khaira.supersetcompanion.core.protocol.LifecyclePushData
import family.khaira.supersetcompanion.core.protocol.PushData
import family.khaira.supersetcompanion.core.wear.WatchActorSurface
import family.khaira.supersetcompanion.core.wear.WatchResolutionOutcome
import family.khaira.supersetcompanion.phone.di.CompanionContainer
import family.khaira.supersetcompanion.phone.model.FetchResult
import family.khaira.supersetcompanion.phone.model.QuestionState
import kotlinx.coroutines.TimeoutCancellationException
import kotlinx.coroutines.runBlocking
import kotlinx.coroutines.withTimeout

/**
 * Receives the wake-up push for a blocked agent.
 *
 * The payload carries OPAQUE IDS ONLY — no question text, no option text, no workspace
 * names. Nothing about what an agent asked may ever reach Google. The real content is
 * fetched from the bridge over the sealed channel once this wakes the app, and if that
 * fetch cannot happen the notification is posted **contentless**. This service never
 * invents text and never renders anything that arrived through FCM.
 *
 * A push here also means something specific: *nobody has dealt with this*. The bridge
 * gates on presence (§13.2) — it holds the push while it believes you are at the desk and
 * sends it when it believes you are away — so reds answered at the keyboard, most of them,
 * never reach this class at all. That is the only reason a watch buzz stays meaningful.
 * The gating is entirely the bridge's; this client applies no delay of its own.
 */
class CompanionMessagingService : FirebaseMessagingService() {

    private val container: CompanionContainer by lazy {
        CompanionContainer.get(applicationContext)
    }

    /**
     * Trigger (c): Firebase rotated this phone's token.
     *
     * Always necessary, never sufficient — a token minted before pairing (the ordinary
     * case, since Firebase mints one on first launch and the QR is scanned minutes later)
     * produces no second `onNewToken`, so this callback alone could never register it. The
     * pairing-success and foreground triggers cover that; this one covers rotation.
     */
    override fun onNewToken(token: String) {
        // The token value itself is never recorded — only that there is one.
        container.pushDiagnostics.recordTokenAcquired(System.currentTimeMillis())
        runBlocking {
            try {
                withTimeout(WORK_TIMEOUT_MS) { container.pushRegistrar.onNewToken(token) }
            } catch (e: TimeoutCancellationException) {
                // (ROTATION-RETRY-FLOOR) Logging is all this catch has to do, but only
                // because the registrar guarantees the retry. A timeout CANCELS the
                // coroutine rather than returning, so nothing inside `onNewToken` past the
                // suspension point runs — including its own RETRY branch — and this catch
                // sits outside the mutex and outside the pairing check, so it is the wrong
                // place to queue one. `PushRegistrar.onNewToken` queues it from a `finally`
                // that does run while cancelled. Remove that and a rotated token is
                // silently dropped again, which is a phone that stops being wakeable.
                Log.e(TAG, "FCM token registration timed out; a retry is queued", e)
            }
        }
    }

    override fun onMessageReceived(message: RemoteMessage) {
        val push = parse(message)
        if (push == null) {
            // Recorded, not just logged: a bridge that sends malformed or notification-bearing
            // pushes is silent-from-the-pocket in exactly the same way as a denied permission.
            container.pushDiagnostics.recordPushRefused(
                System.currentTimeMillis(),
                "malformed or notification-bearing payload — see logcat $TAG",
            )
            return
        }
        when (push) {
            is CompanionPush.Blocked -> onBlocked(push.data)
            is CompanionPush.Lifecycle -> onLifecycle(push.data)
        }
    }

    private fun onBlocked(push: PushData) {
        container.pushDiagnostics.recordPushReceived(
            System.currentTimeMillis(),
            push.kind.name.lowercase(),
        )
        // (PUSH-ROUTING) The decision is `routePush`, which is testable; everything below
        // needs a Context or a coroutine and stays here behind the surface.
        val route = routePush(push, System.currentTimeMillis(), surface)
        if (route == PushRoute.EXPIRED) {
            // A push that outlived its window describes a moment that has passed. Showing
            // it would be worse than showing nothing: the user would walk to the desk for
            // a question that is fifteen minutes stale.
            Log.i(TAG, "dropping expired push for ${push.questionId}")
        }
    }

    private fun onLifecycle(push: LifecyclePushData) {
        container.pushDiagnostics.recordPushReceived(
            System.currentTimeMillis(),
            push.kind.name.lowercase(),
        )
        // (LIFECYCLE-ROUTING) Same split as the question path: the decision is testable,
        // the notification manager and the Data Layer send stay behind the surface.
        val route = routeLifecyclePush(
            push = push,
            nowMs = System.currentTimeMillis(),
            gate = container.seenLifecycleEvents,
            surface = lifecycleSurface,
        )
        when (route) {
            // "An agent finished" is only true of a moment; an expired one describes a
            // workspace the user has probably already looked at.
            LifecycleRoute.EXPIRED -> Log.i(TAG, "dropping expired lifecycle push ${push.eventId}")
            // FCM is at-least-once. A second buzz for one event is the reason a whole
            // alert class gets muted, so it is dropped here rather than deduped by the
            // notification tag, which would still vibrate.
            LifecycleRoute.DUPLICATE -> Log.i(TAG, "already alerted for ${push.eventId}")
            LifecycleRoute.ALERTED -> Unit
        }
    }

    private val surface = object : PushSurface {

        override fun retractNotification(questionId: String) {
            container.notifications.retract(questionId)
        }

        override fun tellWatchResolved(questionId: String) {
            // The watch has no independent route to the desktop, so this message is the
            // only way its screen and its own notification learn the question is over.
            // Provenance is genuinely unknown here — a retract push says a question
            // stopped being answerable, not who ended it — and it is reported as
            // unknown rather than guessed.
            pushToWatch("retract $questionId") {
                container.watchBridge.pushResolved(
                    questionId = questionId,
                    resolvedAtMs = null,
                    resolvedBySurface = WatchActorSurface.UNKNOWN,
                    resolvedByLabel = null,
                    outcome = WatchResolutionOutcome.UNKNOWN,
                )
            }
        }

        override fun deliverQuestion(push: PushData) = postQuestion(push)
    }

    private val lifecycleSurface = object : LifecyclePushSurface {

        /**
         * The phone's own notification is `setLocalOnly`, so the Data Layer send is the
         * only way the wrist hears about it — and it is a send the watch renders itself,
         * in wording written for a watch, instead of a truncated bridged copy.
         */
        override fun post(push: LifecyclePushData) {
            container.notifications.postLifecycle(push)
            pushToWatch("lifecycle ${push.eventId}") {
                container.watchBridge.pushLifecycle(push, System.currentTimeMillis())
            }
        }
    }

    /**
     * Parsing is where a text leak would be caught, so it is deliberately strict: the key
     * set is closed and every value must match an opaque-id pattern that no
     * natural-language string can satisfy (PROTOCOL §13.1 for questions, §13.4 for
     * lifecycle alerts; `CompanionPush.parse` dispatches on `v` and each version's parser
     * refuses every key it does not own).
     *
     * A violation is logged at ERROR and the push is dropped. It is *not* rethrown, and
     * that is a considered trade-off rather than a softened failure: this callback runs
     * inside FCM's delivery path, so throwing would crash the process on every redelivery
     * of the same message — turning one malformed payload into a permanent crash loop that
     * an attacker, or a bridge bug, could hold the app in. Dropping loudly keeps the
     * failure visible without handing anyone a remote kill switch.
     */
    private fun parse(message: RemoteMessage): CompanionPush? {
        if (message.notification != null) {
            // The bridge must send data-only messages. A `notification` block means text
            // came through Google's infrastructure, which is the exact property the
            // payload format exists to make impossible.
            Log.e(
                TAG,
                "REFUSING push carrying a notification block — the bridge must send " +
                    "data-only messages; text must never traverse FCM",
            )
            return null
        }
        return try {
            CompanionPush.parse(message.data)
        } catch (e: ProtocolException) {
            Log.e(TAG, "REFUSING malformed push payload: ${e.message}", e)
            null
        }
    }

    private fun postQuestion(push: PushData) {
        val detail = runBlocking {
            try {
                withTimeout(WORK_TIMEOUT_MS) {
                    container.repository.loadQuestion(push.questionId)
                }
            } catch (e: TimeoutCancellationException) {
                Log.w(TAG, "question fetch timed out for ${push.questionId}", e)
                null
            }
        }

        when (detail) {
            is FetchResult.Success -> {
                val question = detail.value
                if (question.state != QuestionState.PENDING) {
                    // It resolved between the bridge arming the push and this phone waking
                    // up. A notification must never outlive the thing it was about.
                    Log.i(TAG, "push for ${push.questionId} arrived already ${question.state}")
                    container.notifications.retract(push.questionId)
                    pushToWatch("resolved ${push.questionId}") {
                        container.watchBridge.pushQuestionById(push.questionId)
                    }
                    return
                }
                container.notifications.postQuestion(question)
                // The phone's own notification is setLocalOnly, so it is deliberately NOT
                // bridged to the wrist — a bridged copy would be the 1 024-character
                // truncation this product exists to avoid. The Data Layer carries the full
                // question instead, and this is where that starts.
                pushToWatch("question ${push.questionId}") {
                    container.watchBridge.pushQuestion(question)
                }
            }

            is FetchResult.Failure -> {
                // Offline, revoked, or the desktop went away between arming and delivery.
                // The user still learns that something is blocked; they just have to open
                // the app to find out what. Inventing a headline here would be a lie.
                Log.w(TAG, "could not fetch ${push.questionId}: ${detail.error.message}")
                container.notifications.postContentless(push.questionId, push.questionCount)
                warnWatchNotToldOf(push.questionId)
            }

            null -> {
                container.notifications.postContentless(push.questionId, push.questionCount)
                warnWatchNotToldOf(push.questionId)
            }
        }
    }

    /**
     * Runs one bounded Data Layer push.
     *
     * Blocking, like the rest of this service: an FCM callback may be torn down as soon as
     * it returns, so work launched asynchronously here is work that may never happen. A
     * timeout is logged and does not affect the phone's own notification, which is already
     * posted — the wrist is a second surface, never a precondition for the first.
     */
    private fun pushToWatch(what: String, block: suspend () -> Unit) {
        runBlocking {
            try {
                withTimeout(WATCH_TIMEOUT_MS) { block() }
            } catch (e: TimeoutCancellationException) {
                Log.w(TAG, "watch push timed out: $what", e)
            }
        }
    }

    /**
     * A contentless push means this phone could not fetch the body, and the Data Layer
     * contract has no contentless question — inventing one would be a message the watch
     * cannot decode. The watch catches up on its next foreground `hello`, which asks for
     * whatever is still pending. Logged so the gap is visible rather than assumed.
     */
    private fun warnWatchNotToldOf(questionId: String) {
        Log.w(TAG, "no body for $questionId, so the watch was not told; it will ask on next hello")
    }

    private companion object {
        const val TAG = "CompanionPush"

        /**
         * FCM allows roughly 20 s of work in this callback before it stops holding a
         * wakelock. Staying well inside that keeps the fetch from being killed mid-flight
         * and leaving neither a notification nor a log line.
         */
        const val WORK_TIMEOUT_MS = 12_000L

        /**
         * A Data Layer hop to a watch that may be asleep on the wrist. Play Services'
         * own send timeout is 10 s (see `WatchLink`); this bounds the whole push.
         */
        const val WATCH_TIMEOUT_MS = 12_000L
    }
}

package family.khaira.supersetcompanion.phone.notifications

import android.content.Context
import family.khaira.supersetcompanion.push.LifecycleAlertGate

/**
 * The store behind [SeenLifecycleEvents], split out so the ring logic is testable off
 * device. One small file of ids; no migration story worth having.
 */
interface SeenEventStore {

    /** Oldest first. */
    fun read(): List<String>

    fun write(eventIds: List<String>)
}

/**
 * (LIFECYCLE-DEDUPE) One alert per event, across process death.
 *
 * In-memory would have been enough for FCM's own retries within a session and wrong
 * everywhere else: [family.khaira.supersetcompanion.push.CompanionMessagingService] is
 * constructed per message, and a phone that was dozing gets its process killed between
 * the first delivery and the redelivery. The buzz that survives a restart is exactly the
 * one the user would call a bug.
 *
 * Bounded to [CAPACITY] ids, oldest evicted first. An unbounded list would grow with every
 * agent run for the life of the install, and the alerts worth deduping are recent by
 * construction — an event id that fell off the end is one whose notification the user
 * dealt with days ago.
 */
class SeenLifecycleEvents(
    private val store: SeenEventStore,
    private val capacity: Int = CAPACITY,
) : LifecycleAlertGate {

    init {
        require(capacity > 0) { "a dedupe window of $capacity events remembers nothing" }
    }

    @Synchronized
    override fun admit(eventId: String): Boolean {
        val seen = store.read()
        if (eventId in seen) return false
        store.write((seen + eventId).takeLast(capacity))
        return true
    }

    companion object {
        /** Days of alerts on a busy machine, and a few hundred bytes on disk. */
        const val CAPACITY = 64
    }
}

/** The on-disk implementation. */
class SharedPreferencesSeenEventStore(context: Context) : SeenEventStore {

    private val prefs = context.getSharedPreferences(FILE, Context.MODE_PRIVATE)

    override fun read(): List<String> =
        prefs.getString(KEY_EVENT_IDS, null)
            ?.split(SEPARATOR)
            ?.filter { it.isNotEmpty() }
            ?: emptyList()

    override fun write(eventIds: List<String>) {
        // commit(), not apply(): this runs on FCM's delivery thread and the process is
        // routinely killed moments after onMessageReceived returns. An apply() that had
        // not reached disk would lose exactly the record the redelivery is checked
        // against — the buzz-twice bug this store exists to prevent.
        prefs.edit().putString(KEY_EVENT_IDS, eventIds.joinToString(SEPARATOR)).commit()
    }

    private companion object {
        const val FILE = "companion_lifecycle_alerts"
        const val KEY_EVENT_IDS = "seen_event_ids"

        /**
         * Safe as a separator because event ids are base64url — the character set that
         * [family.khaira.supersetcompanion.core.protocol.Ids.requireOpaque16] enforces
         * excludes it, so no id can ever split itself in two.
         */
        const val SEPARATOR = ","
    }
}

package family.khaira.supersetcompanion.phone.notifications

import android.Manifest
import android.app.Notification
import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.content.Context
import android.content.Intent
import android.content.pm.PackageManager
import android.util.Log
import androidx.core.app.NotificationCompat
import androidx.core.content.ContextCompat
import family.khaira.supersetcompanion.MainActivity
import family.khaira.supersetcompanion.R
import family.khaira.supersetcompanion.core.protocol.LifecycleKind
import family.khaira.supersetcompanion.core.protocol.LifecyclePushData
import family.khaira.supersetcompanion.phone.model.QuestionDetail
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow

/**
 * Every notification this app posts, and — more importantly — every one it takes away.
 *
 * A notification must never outlive the thing it was about. Retraction over FCM is
 * best-effort (a dozing phone misses it), so [sweep] runs a full reconciliation against
 * the desktop's own list on **every** foreground. That is not belt-and-braces: the
 * likeliest stale buzz in real use comes from exactly the dozing case the push cannot
 * reach.
 *
 * Nothing here invents text. The push payload carries opaque ids only — no question text,
 * no option text, no workspace or branch name ever reaches Google — so when the question
 * body cannot be fetched over the sealed channel this posts a *contentless* notification
 * rather than a plausible-looking one.
 */
class CompanionNotifications(private val context: Context) : LostContactSurface {

    private val manager: NotificationManager =
        context.getSystemService(NotificationManager::class.java)
            ?: error("NotificationManager unavailable — the platform contract guarantees it")

    private val deliveryState = MutableStateFlow(readDelivery())

    /**
     * Whether a blocked-agent notification would actually reach the user right now.
     *
     * Android gives no callback when the permission is revoked or the channel is muted from
     * system settings, so this is a poll: [refreshDelivery] runs on every foreground and
     * after every attempt to post. That is enough — the states it reports can only be
     * changed by the user leaving the app to change them.
     */
    val delivery: StateFlow<NotificationDelivery> = deliveryState.asStateFlow()

    fun refreshDelivery() {
        deliveryState.value = readDelivery()
    }

    private fun readDelivery(): NotificationDelivery {
        val channel = manager.getNotificationChannel(CHANNEL_QUESTIONS)
        return NotificationDelivery(
            permissionGranted = canPost(),
            appEnabled = manager.areNotificationsEnabled(),
            questionsChannelImportance = channel?.importance,
        )
    }

    fun ensureChannels() {
        manager.createNotificationChannel(
            NotificationChannel(
                CHANNEL_QUESTIONS,
                "Blocked agents",
                NotificationManager.IMPORTANCE_HIGH,
            ).apply {
                description =
                    "An agent is blocked and you were not at the desk to see it. These are " +
                    "the only notifications that can be answered from the phone."
                enableVibration(true)
                setShowBadge(true)
            },
        )
        manager.createNotificationChannel(
            NotificationChannel(
                CHANNEL_READY,
                "Ready for review",
                NotificationManager.IMPORTANCE_DEFAULT,
            ).apply {
                description =
                    "An agent finished and its work is waiting for you. Nothing is blocked, " +
                    "so this does not vibrate — turn it off here if you would rather find " +
                    "finished work yourself."
                enableVibration(false)
                setShowBadge(true)
            },
        )
        manager.createNotificationChannel(
            NotificationChannel(
                CHANNEL_ERROR,
                "Agent errors",
                NotificationManager.IMPORTANCE_HIGH,
            ).apply {
                description =
                    "An agent stopped on an error. Nothing is blocked on an answer either — " +
                    "it simply will not continue on its own."
                enableVibration(true)
                setShowBadge(true)
            },
        )
        manager.createNotificationChannel(
            NotificationChannel(
                CHANNEL_LIVENESS,
                "Lost contact",
                NotificationManager.IMPORTANCE_DEFAULT,
            ).apply {
                description =
                    "The desktop stopped answering while agents were still running. Raised " +
                    "locally by this phone, not by the desktop — which is the point."
                setShowBadge(false)
            },
        )
        // The first read happened before the channels existed; without this the app would
        // report its own "channel missing" fault for the lifetime of the process.
        refreshDelivery()
    }

    /** True when this app holds `POST_NOTIFICATIONS`. See [delivery] for whether it lands. */
    fun canPost(): Boolean =
        ContextCompat.checkSelfPermission(context, Manifest.permission.POST_NOTIFICATIONS) ==
            PackageManager.PERMISSION_GRANTED

    /**
     * Posts a question the phone has successfully fetched. The text here came over the
     * sealed channel, never through Google.
     */
    fun postQuestion(detail: QuestionDetail) {
        val first = detail.questions.firstOrNull()
            ?: error("question ${detail.questionId} has no items — the bridge must not send that")
        val title = first.header.ifBlank { "An agent needs you" }
        val body = if (detail.isMultiPart) {
            "${detail.questions.size} questions · tap to answer"
        } else {
            first.question
        }
        post(
            questionId = detail.questionId,
            title = title,
            body = body,
            answerable = detail.answerable,
        )
    }

    /**
     * Posts when the question body could not be fetched — offline, revoked, rate-limited.
     * Contentless on purpose: inventing a summary from an opaque id would be a lie, and
     * the id is genuinely all we have.
     */
    fun postContentless(questionId: String, questionCount: Int) {
        post(
            questionId = questionId,
            title = "An agent needs you",
            body = if (questionCount > 1) {
                "$questionCount questions waiting — open to read them"
            } else {
                "Open to read the question"
            },
            answerable = true,
        )
    }

    /**
     * (LIFECYCLE-ALERT) An agent finished, or stopped on an error. Fixed wording, chosen
     * locally and driven only by [LifecyclePushData.kind].
     *
     * There is nothing to fetch and nothing to fetch it with: a lifecycle push carries
     * opaque ids only, and unlike a question there is no body endpoint that would make
     * the text more specific. So the phone says the one true thing it knows and lets the
     * app say the rest. The tap opens the app at home — not a question, because there is
     * no question, and an alert whose tap lands somewhere unanswerable teaches the user
     * to stop tapping.
     */
    fun postLifecycle(push: LifecyclePushData) {
        val alert = lifecycleAlert(push.kind)
        if (!canPost()) {
            refreshDelivery()
            Log.w(TAG, "notification permission not granted; ${alert.channelId} alert not posted")
            return
        }
        val notification = NotificationCompat.Builder(context, alert.channelId)
            .setSmallIcon(R.drawable.ic_notification)
            .setContentTitle(alert.title)
            .setContentText(alert.body)
            .setContentIntent(openAppIntent(null))
            .setCategory(alert.category)
            .setPriority(alert.priority)
            .setAutoCancel(true)
            .setOnlyAlertOnce(true)
            // The watch gets its own alert over the Data Layer (WearPaths.LIFECYCLE), with
            // wording written for a wrist. Without this the wrist shows both that and a
            // bridged copy of this one, for one event.
            .setLocalOnly(true)
            .build()
        // Tagged by the alert id, which is what identifies a lifecycle alert everywhere
        // else too — the bridge's collapse_key, the dedupe window, and the watch's own
        // notification id. A redelivery updates its own row; a different event is a
        // different fact and gets its own.
        manager.notify(push.eventId, ID_LIFECYCLE, notification)
    }

    private fun lifecycleAlert(kind: LifecycleKind): LifecycleAlert = when (kind) {
        LifecycleKind.READY -> LifecycleAlert(
            channelId = CHANNEL_READY,
            title = "An agent finished",
            body = "Ready for review — open Superset to look over the work.",
            category = Notification.CATEGORY_STATUS,
            priority = NotificationCompat.PRIORITY_DEFAULT,
        )

        LifecycleKind.ERROR -> LifecycleAlert(
            channelId = CHANNEL_ERROR,
            title = "An agent stopped on an error",
            body = "It will not continue on its own — open Superset to see what happened.",
            category = Notification.CATEGORY_ERROR,
            priority = NotificationCompat.PRIORITY_HIGH,
        )
    }

    /** Everything one lifecycle kind changes about the notification, in one place. */
    private class LifecycleAlert(
        val channelId: String,
        val title: String,
        val body: String,
        val category: String,
        val priority: Int,
    )

    override fun postLostContact(workingCount: Int, needsInputCount: Int) {
        if (!canPost()) {
            refreshDelivery()
            Log.w(TAG, "notification permission not granted; lost-contact warning not posted")
            return
        }
        val notification = NotificationCompat.Builder(context, CHANNEL_LIVENESS)
            .setSmallIcon(R.drawable.ic_notification)
            .setContentTitle("Lost contact with the desktop")
            .setContentText(
                "$needsInputCount waiting, $workingCount working at last contact. " +
                    "Agents keep running when Superset closes.",
            )
            .setStyle(
                NotificationCompat.BigTextStyle().bigText(
                    "$needsInputCount waiting for an answer and $workingCount working when the " +
                        "desktop last answered. The agents keep running under the detached pty " +
                        "daemon even though the bridge is gone, so this may need attention at " +
                        "the machine.",
                ),
            )
            .setContentIntent(openAppIntent(null))
            .setCategory(Notification.CATEGORY_STATUS)
            .setAutoCancel(true)
            // The watchdog can re-assert lost contact on any diagnostics change while the
            // desktop is still gone. Updating the counts in place is right; alerting again
            // for the same outage is not.
            .setOnlyAlertOnce(true)
            .build()
        manager.notify(TAG_LIVENESS, ID_LIVENESS, notification)
    }

    override fun cancelLostContact() = manager.cancel(TAG_LIVENESS, ID_LIVENESS)

    /** Retracts one question's notification, from either a push or a local resolution. */
    fun retract(questionId: String) {
        manager.cancel(questionId, ID_QUESTION)
    }

    /**
     * The full foreground sweep. Cancels every posted question notification that the
     * desktop no longer reports as pending.
     *
     * @param stillPending question ids the desktop currently reports as unanswered.
     * @return the ids that were retracted, for logging — a silent sweep would hide a bug
     *   in whatever was supposed to have retracted them already.
     */
    fun sweep(stillPending: Set<String>): List<String> {
        val posted = manager.activeNotifications
            .filter { it.id == ID_QUESTION }
            .mapNotNull { it.tag }
        val stale = posted.filterNot { it in stillPending }
        stale.forEach { manager.cancel(it, ID_QUESTION) }
        if (stale.isNotEmpty()) {
            Log.i(TAG, "foreground sweep retracted ${stale.size} stale notification(s): $stale")
        }
        return stale
    }

    /** Question ids this phone currently has on screen. */
    fun postedQuestionIds(): Set<String> =
        manager.activeNotifications
            .filter { it.id == ID_QUESTION }
            .mapNotNull { it.tag }
            .toSet()

    private fun post(questionId: String, title: String, body: String, answerable: Boolean) {
        if (!canPost()) {
            // Loud in the log AND on screen: a dropped question notification is the whole
            // product failing, and this is the moment the app learns it is happening.
            refreshDelivery()
            Log.w(TAG, "notification permission not granted; question $questionId not posted")
            return
        }
        refreshDelivery()
        val builder = NotificationCompat.Builder(context, CHANNEL_QUESTIONS)
            .setSmallIcon(R.drawable.ic_notification)
            .setContentTitle(title)
            .setContentText(body.lineSequence().firstOrNull().orEmpty())
            .setStyle(NotificationCompat.BigTextStyle().bigText(body))
            .setContentIntent(openAppIntent(questionId))
            .setCategory(Notification.CATEGORY_MESSAGE)
            .setPriority(NotificationCompat.PRIORITY_HIGH)
            .setAutoCancel(true)
            .setOnlyAlertOnce(true)

