1	import type { SelectV2Workspace } from "@superset/db/schema";
2	import {
3		KANBAN_COMPLETED_COLUMN_ID,
4		type KanbanCardRow,
5		kanbanBoundCardId,
6	} from "renderer/routes/_authenticated/providers/CollectionsProvider/dashboardSidebarLocal";
7	import { buildCompletedContext } from "../completedFilter";
8	import { deriveCardTitle } from "../deriveCardTitle";
9	
10	export type CompletableWorkspace = Pick<
11		SelectV2Workspace,
12		"id" | "projectId" | "type" | "name" | "branch" | "hostId"
13	>;
14	
15	export type CompletionSectionState = "snoozed" | "archived" | "deleted";
16	
17	export function canMarkWorkspaceCompleted(
18		workspace: Pick<SelectV2Workspace, "projectId" | "type">,
19		sectionState: CompletionSectionState | undefined,
20		projectIsInSidebar: boolean,
21	): boolean {
22		return (
23			sectionState === undefined &&
24			workspace.type === "worktree" &&
25			projectIsInSidebar &&
26			workspace.projectId !== null
27		);
28	}
29	
30	export function buildCompletedWorkspaceCard({
31		workspace,
32		projectName,
33		existingCard,
34		completedAt,
35	}: {
36		workspace: CompletableWorkspace;
37		projectName: string | null;
38		existingCard: KanbanCardRow | null;
39		completedAt: number;
40	}): KanbanCardRow {
41		if (workspace.type !== "worktree") {
42			throw new Error(
43				`Cannot complete non-worktree workspace ${workspace.id} (${workspace.type})`,
44			);
45		}
46		if (workspace.projectId === null) {
47			throw new Error(`Cannot complete project-less workspace ${workspace.id}`);
48		}
49		if (existingCard?.workspaceId && existingCard.workspaceId !== workspace.id) {
50			throw new Error(
51				`Cannot complete workspace ${workspace.id} using card ${existingCard.id} bound to ${existingCard.workspaceId}`,
52			);
53		}
54	
55		return {
56			id: existingCard?.id ?? kanbanBoundCardId(workspace.id),
57			columnId: KANBAN_COMPLETED_COLUMN_ID,
58			tabOrder: 0,
59			title: deriveCardTitle(workspace),
60			description: existingCard?.description ?? null,
61			deadline: existingCard?.deadline ?? null,
62			deadlineTabOrder: null,
63			workspaceId: workspace.id,
64			hostId: existingCard?.hostId ?? workspace.hostId,
65			snoozeUntil: existingCard?.snoozeUntil ?? null,
66			snoozeLaunchId: existingCard?.snoozeLaunchId ?? null,
67			archivedAt: existingCard?.archivedAt ?? null,
68			completedAt,
69			completedContext: buildCompletedContext(projectName, workspace.branch),
70			deletedAt: existingCard?.deletedAt ?? null,
71			createdAt: existingCard?.createdAt ?? completedAt,
72		};
73	}
