49		) => void;
50		restoreQueuedCard: (
51			snapshot: KanbanCardRow,
52			optimisticWorkspaceId: string,
53		) => void;
54		rebindPromotedCard: (fromWorkspaceId: string, toWorkspaceId: string) => void;
