111	 * shared DeleteWorkspaceDialog (the board's reconcile then drops the card).
112	 */
113	export function useKanbanActions(): UseKanbanActionsResult {
114		const collections = useCollections();
115		const {
116			archiveWorkspace,
117			deleteWorkspace,
118			restoreWorkspace,
119			snoozeWorkspace,
120			uncompleteWorkspace,
121			unsnoozeWorkspace,
122			unarchiveWorkspaces,
123			ensureWorkspaceInSidebar,
