130	
131		// (KANBAN HOST SOURCE) Workspace lookups go to the host-served lists, not
132		// the dead Electric mirror (see useKanbanData).
133		const { workspaces: hostWorkspaces, isAbsenceAuthoritative } =
134			useHostWorkspaces();
135		const hostWorkspaceById = useMemo(() => {
136			const map = new Map<string, (typeof hostWorkspaces)[number]>();
137			for (const w of hostWorkspaces) map.set(w.id, w);
138			return map;
139		}, [hostWorkspaces]);
140	
141		const columnCards = useCallback(
142			(columnId: string) =>
143				Array.from(collections.v2KanbanCards.state.values()).filter(
144					(c) => c.columnId === columnId,
145				),
146			[collections],
147		);
148	
149		const customColumnsOrdered = useCallback(
150			() =>
151				Array.from(collections.v2KanbanColumns.state.values())
152					.filter(
153						(c) =>
154							!c.isQueue &&
155							c.id !== KANBAN_QUEUE_COLUMN_ID &&
156							!c.isCompleted &&
157							c.id !== KANBAN_COMPLETED_COLUMN_ID,
158					)
159					.sort((a, b) => a.tabOrder - b.tabOrder),
160			[collections],
161		);
162	
163		const ensureBoundRow = useCallback(
164			(workspaceId: string) => {
165				if (collections.v2WorkspaceLocalState.get(workspaceId)) return;
166				const ws = hostWorkspaceById.get(workspaceId);
167				if (ws) ensureWorkspaceInSidebar(workspaceId, ws.projectId);
168			},
169			[collections, hostWorkspaceById, ensureWorkspaceInSidebar],
170		);
171	
172		const createQueuedCard = useCallback(
173			(title?: string) => {
174				const id = crypto.randomUUID();
175				const tabOrder = getNextTabOrder(columnCards(KANBAN_QUEUE_COLUMN_ID));
176				collections.v2KanbanCards.insert({
177					id,
178					columnId: KANBAN_QUEUE_COLUMN_ID,
179					tabOrder,
180					title: title ?? "",
181					description: null,
182					deadline: null,
183					deadlineTabOrder: null,
184					workspaceId: null,
185					hostId: null,
186					snoozeUntil: null,
187					snoozeLaunchId: null,
188					archivedAt: null,
189					completedAt: null,
190					completedContext: null,
191					createdAt: Date.now(),
192				});
193				return id;
194			},
195			[collections, columnCards],
196		);
197	
198		const updateCard = useCallback<UseKanbanActionsResult["updateCard"]>(
199			(cardId, patch) => {
200				if (!collections.v2KanbanCards.get(cardId)) return;
201				collections.v2KanbanCards.update(cardId, (draft) =>
202					applyKanbanCardPatch(draft, patch),
203				);
204			},
205			[collections],
206		);
207	
208		const canDropCard = useCallback<UseKanbanActionsResult["canDropCard"]>(
209			(card, toColumnId, workspaceType) => {
210				const toQueue = toColumnId === KANBAN_QUEUE_COLUMN_ID;
211				// (KANBAN COMPLETED) ANY card can complete except a repo's main
212				// workspace (completing hides the sidebar row — a hidden main has no
213				// restore path since un-completion is dragging the card back out, and
214				// main rows must always be reachable). Unbound cards complete directly
215				// — completing a task is NOT a promote (no branch gets created).
216				if (toColumnId === KANBAN_COMPLETED_COLUMN_ID) {
