224				return toQueue ? "ok" : "promote";
225			},
226			[],
227		);
228	
229		const applyCardOrder = useCallback(
230			(columnId: string, orderedCardIds: string[]) => {
231				// Batched update: one transaction = ONE localStorage flush for the whole
232				// column (the driver re-serializes the entire per-org blob per
233				// transaction, so per-card updates paid N flushes per drop).
234				const ids = orderedCardIds.filter((id) =>
235					collections.v2KanbanCards.get(id),
236				);
237				if (ids.length === 0) return;
238				collections.v2KanbanCards.update(ids, (drafts) => {
239					drafts.forEach((draft, index) => {
240						// (DEADLINE-TIE-ORDER) a card entering a DIFFERENT column arrives
241						// in that column's tie groups as a NEW item; same-column manual
242						// reorders never touch the deadline-mode order.
243						if (draft.columnId !== columnId) draft.deadlineTabOrder = null;
244						draft.columnId = columnId;
245						draft.tabOrder = index + 1;
246					});
247				});
248			},
249			[collections],
250		);
251	
252		const applyDeadlineTieOrder = useCallback(
253			(orderedCardIds: string[], resetCardIds: string[] = []) => {
254				// (DEADLINE-TIE-ORDER) Persist a drag done in deadline sort mode:
255				// numbers the dragged card's whole displayed tie group, and RESETS the
256				// group's hidden (snoozed/archived) members to null — their placement
257				// context changed while hidden, so they return as new arrivals at the
258				// bottom instead of interleaving with a stale number. NEVER touches
259				// tabOrder — the manual order survives mode round-trips. One batched
260				// transaction = one localStorage flush.
261				const orderIds = orderedCardIds.filter((id) =>
262					collections.v2KanbanCards.get(id),
263				);
264				const resetIds = resetCardIds.filter(
265					(id) => !orderIds.includes(id) && collections.v2KanbanCards.get(id),
266				);
267				const ids = [...orderIds, ...resetIds];
268				if (ids.length === 0) return;
269				collections.v2KanbanCards.update(ids, (drafts) => {
270					drafts.forEach((draft, index) => {
271						draft.deadlineTabOrder = index < orderIds.length ? index + 1 : null;
272					});
273				});
274			},
275			[collections],
276		);
277	
278		const moveCardToColumn = useCallback(
279			(cardId: string, toColumnId: string) => {
280				if (!collections.v2KanbanCards.get(cardId)) return;
281				const tabOrder = getNextTabOrder(columnCards(toColumnId));
282				collections.v2KanbanCards.update(cardId, (draft) => {
283					draft.columnId = toColumnId;
284					draft.tabOrder = tabOrder;
285					// (DEADLINE-TIE-ORDER) new column = new tie groups; arrive as a
286					// NEW item (below the explicitly ordered cards of its group).
287					draft.deadlineTabOrder = null;
288				});
289			},
290			[collections, columnCards],
291		);
292	
293		const completePromote = useCallback(
294			(queuedCardId: string, workspaceId: string, toColumnId: string) => {
295				const queued = collections.v2KanbanCards.get(queuedCardId);
296				// Fail fast: only promote an existing UNBOUND card into a real non-Queue
297				// column (guards against stale dialogs). NOTE: we do NOT require the
298				// v2Workspaces row to exist yet — the caller awaited a confirmed create
299				// outcome, but the optimistic/synced row may lag a tick; the bound card
300				// is keyed by workspaceId and reconcile aligns it.
301				if (!queued || queued.workspaceId) return;
302				const targetColumn = collections.v2KanbanColumns.get(toColumnId);
303				// Completed is no promote target either: a freshly-created branch must
304				// never be born completed (drops on Completed return "ok", not
305				// "promote", so this is unreachable via the board — belt and braces).
306				if (!targetColumn || targetColumn.isQueue || targetColumn.isCompleted) {
307					return;
308				}
309				const tabOrder = getNextTabOrder(columnCards(toColumnId));
310				const boundId = kanbanBoundCardId(workspaceId);
311				const existing = collections.v2KanbanCards.get(boundId);
312				if (existing) {
313					// Merge the Queued task metadata into the branch's existing card
314					// (non-git main, or a git branch-name collision). One card per branch.
315					collections.v2KanbanCards.update(boundId, (draft) => {
316						// (DEADLINE-TIE-ORDER) merged into a different column or tie
317						// group → arrives as a NEW item; an in-place merge keeps its order.
318						const columnChanged = draft.columnId !== toColumnId;
319						const deadlineChanged =
320							queued?.deadline != null && queued.deadline !== draft.deadline;
321						draft.columnId = toColumnId;
322						draft.tabOrder = tabOrder;
323						if (queued?.title) draft.title = queued.title;
324						if (queued?.description != null)
325							draft.description = queued.description;
326						if (queued?.deadline != null) draft.deadline = queued.deadline;
327						if (columnChanged || deadlineChanged) draft.deadlineTabOrder = null;
328					});
329				} else {
330					collections.v2KanbanCards.insert({
331						id: boundId,
332						columnId: toColumnId,
333						tabOrder,
334						title: queued?.title || "",
335						description: queued?.description ?? null,
336						deadline: queued?.deadline ?? null,
337						deadlineTabOrder: null,
338						workspaceId,
339						hostId: hostWorkspaceById.get(workspaceId)?.hostId ?? null,
340						snoozeUntil: null,

