import { useCallback, useMemo } from "react";
import { useHostProjects } from "renderer/hooks/host-projects/useHostProjects";
import { useDashboardSidebarState } from "renderer/routes/_authenticated/hooks/useDashboardSidebarState";
import { useCollections } from "renderer/routes/_authenticated/providers/CollectionsProvider";
import { kanbanBoundCardId } from "renderer/routes/_authenticated/providers/CollectionsProvider/dashboardSidebarLocal";
import { useHostWorkspaces } from "renderer/routes/_authenticated/providers/HostWorkspacesProvider";
import { buildCompletedWorkspaceCard } from "../../utils/completeWorkspaceCard";

export type CompleteWorkspaceCardResult =
	| { ok: true }
	| { ok: false; reason: string; canFreezeCard: boolean };

export function useCompleteWorkspaceCard() {
	const collections = useCollections();
	const { completeWorkspace, ensureWorkspaceInSidebar } =
		useDashboardSidebarState();
	const { projects } = useHostProjects();
	const { workspaces } = useHostWorkspaces();

	const projectNameById = useMemo(() => {
		const names = new Map<string, string>();
		for (const project of projects) names.set(project.projectKey, project.name);
		return names;
	}, [projects]);
	const workspaceById = useMemo(() => {
		const byId = new Map<string, (typeof workspaces)[number]>();
		for (const workspace of workspaces) byId.set(workspace.id, workspace);
		return byId;
	}, [workspaces]);

	return useCallback(
		(
			workspaceId: string,
			requestedCardId?: string,
		): CompleteWorkspaceCardResult => {
			const cardId = requestedCardId ?? kanbanBoundCardId(workspaceId);
			const existingCard = collections.v2KanbanCards.get(cardId) ?? null;
			if (requestedCardId && !existingCard) {
				return {
					ok: false,
					reason: `Kanban card ${requestedCardId} no longer exists`,
					canFreezeCard: false,
				};
			}

			const workspace = workspaceById.get(workspaceId);
			if (!workspace) {
				return {
					ok: false,
					reason: `Workspace ${workspaceId} no longer exists`,
					canFreezeCard: existingCard !== null,
				};
			}
			if (
				workspace.type !== "worktree" ||
				workspace.projectId === null ||
				!collections.v2SidebarProjects.get(workspace.projectId)
			) {
				return {
					ok: false,
					reason: `Workspace ${workspaceId} is not eligible for Kanban completion`,
					canFreezeCard: existingCard !== null,
				};
			}
			const hasLocalState = collections.v2WorkspaceLocalState.get(workspaceId);

			if (!hasLocalState) {
				ensureWorkspaceInSidebar(workspaceId, workspace.projectId);
				if (!collections.v2WorkspaceLocalState.get(workspaceId)) {
					throw new Error(
						`Failed to create sidebar state before completing ${workspaceId}`,
					);
				}
			}

			const completedAt = Date.now();
			const completedCard = buildCompletedWorkspaceCard({
				workspace,
				projectName: projectNameById.get(workspace.projectId) ?? null,
				existingCard,
				completedAt,
			});

			if (existingCard) {
				collections.v2KanbanCards.update(cardId, (draft) => {
					Object.assign(draft, completedCard);
				});
			} else {
				collections.v2KanbanCards.insert(completedCard);
			}
			completeWorkspace(workspaceId, completedAt);
			return { ok: true };
		},
		[
			collections,
			completeWorkspace,
			ensureWorkspaceInSidebar,
			projectNameById,
			workspaceById,
		],
	);
}

