/** [WatchLifecycleAlert.kind]. */
object WatchLifecycleKind {
    const val READY = "ready"
    const val ERROR = "error"
}

/**
 * An agent finished, or an agent failed (PROTOCOL.md §13.4).
 *
 * Content-free by construction, exactly like the FCM payload it came from: [eventId] and
 * [workspaceId] are opaque and the watch renders fixed local wording. There is no
 * headline, no source label and no item list here — not because they would not fit, but
 * because a lifecycle alert has nothing to say that the user's own workspace does not
 * already say better once they open it.
 *
 * There is no answer path either. The watch alerts once, on its own channels, and opens
 * the app at home when tapped; the question state machine never sees it.
 */
@Serializable
data class WatchLifecycleAlert(
    /** [WatchLifecycleKind]. */
    val kind: String,
    /** Opaque; identity of the alert, used to alert once and to address its notification. */
    val eventId: String,
    /** Opaque; identity of the workspace the alert is about. */
    val workspaceId: String,
    val raisedAtMs: Long,
    /**
     * Carried through from the push (§13.4 `x`), because the wrist needs its own boundary.
     *
     * The phone checks expiry before it sends, but that answers a question about a
     * different moment and a different clock. This hop is best-effort — `MessageClient`
     * delivers to a connected node or fails; it does NOT queue for a watch that is out of
     * range — yet the watch can still take the message minutes later, because the phone
     * only sends after its own wake-up, notification post and Data Layer round trip, and
     * the watch may be asleep when it lands. The watch re-checks rather than trusting a
     * decision made before the hop.
     */
    val expiresAtMs: Long,
) {
    /** Inclusive, matching every other expiry gate in the protocol. */
    fun isExpired(nowMs: Long): Boolean = nowMs >= expiresAtMs
}

/**
 * The outcome of an answer the watch sent, or of a status read.
 *
 * The same `requestId` is reported more than once by design — a §11.5 status read comes back
 * on this same path — and a later report may claim LESS than an earlier one. Which reports
 * may replace which is [WatchAnswerStatus.supersedes], not arrival order: `confirmed` is
 * terminal, `failed` yields only to `confirmed`, and `unconfirmed`/`unknown` yield to
 * anything.
 */
