data class WatchAnswerResult(
    val requestId: String,
    val questionId: String,
    /** [WatchAnswerStatus]. PROTOCOL.md §11.6. */
    val status: String,
    /** A [WatchFailureCode] when [status] is "failed". Null otherwise. */
    val failureCode: String? = null,
    /** Human detail for the failure, e.g. the lease holder's label or the failed guard. */
    val failureDetail: String? = null,
    val resolvedAtMs: Long? = null,
)

/** What the phone believes about its own route to the desktop; maps onto `core.ConnectionState`. */
@Serializable
data class WatchConnection(
    /** [WatchConnectionState]. */
    val state: String,
    val detail: String? = null,
    val httpStatus: Int? = null,
)

// ---------------------------------------------------------------------------
// watch -> phone
// ---------------------------------------------------------------------------

/**
 * Semantic intent. Every field except [surface] is forwarded verbatim into
 * `POST /v1/answer`; [requestId] is minted ONCE by the watch and must never be regenerated
 * for the same user action, or PROTOCOL.md §11.4 idempotency stops protecting it.
 */
@Serializable
data class WatchAnswerIntent(
    val questionId: String,
    val fingerprint: String,
    /** UUIDv4, lowercase, hyphenated. Watch-minted, stable for this attempt. */
    val requestId: String,
    /** One per item, in ascending `questionIndex` order, ALL of them. */
    val answers: List<WatchAnswerItem>,
    /**
     * The bridge's deliberate-send claim (2026-08-09): `true` whenever [answers] carries a
     * `freetext` item, because `POST /v1/answer` hard-requires it there — no biometric
     * ceremony backs it on any surface anymore. False on option-only sends. The phone's
