 *
 * `select`, `multiselect` and `freetext` all exist since 2026-08-09 — the watch renders
 * checkbox rows and takes free text through the system RemoteInput sheet. A build skew
 * (old counterpart, new item kind) fails loudly at deserialisation on the unknown
 * discriminator; phone and watch APKs ship in lockstep. Adding a member here is a
 * protocol change, not a UI change.
 */
@Serializable
sealed class WatchAnswerItem {
    abstract val questionIndex: Int

package family.khaira.supersetcompanion.wear.datalayer

import android.util.Log
import com.google.android.gms.wearable.MessageEvent
import com.google.android.gms.wearable.WearableListenerService
import family.khaira.supersetcompanion.core.wear.WatchAnswerResult
import family.khaira.supersetcompanion.core.wear.WatchAnswerStatus
import family.khaira.supersetcompanion.core.wear.WatchLifecycleAlert
import family.khaira.supersetcompanion.core.wear.WatchQuestion
import family.khaira.supersetcompanion.core.wear.WatchQuestionOversize
import family.khaira.supersetcompanion.core.wear.WatchQuestionResolved
import family.khaira.supersetcompanion.core.wear.WearJson
import family.khaira.supersetcompanion.core.wear.WearPaths
import family.khaira.supersetcompanion.wear.notify.LifecycleNotifier
import family.khaira.supersetcompanion.wear.notify.NotificationBridging
import family.khaira.supersetcompanion.wear.notify.QuestionNotifier
import family.khaira.supersetcompanion.wear.state.QuestionStore
import kotlinx.serialization.SerializationException
import kotlinx.serialization.decodeFromString

private const val TAG = "CompanionWearListener"

/**
 * The watch's only route to anything. It has no independent path to the desktop, so
 * every question and every answer travels through the phone over the Data Layer.
 *
 * This silently delivers nothing if app-watch and app-phone differ in applicationId or
 * signing key — no error, no callback. Both are pinned in the two build files.
 *
 * Error policy here, deliberate:
 *  * An **unknown path** is ignored with a warning. A newer phone build must be able to add
 *    a message type without bricking an older watch (PROTOCOL.md §0 forward compatibility).
 *  * An **undecodable payload on a known path** throws. That is not forward compatibility,
 *    it is the two sides disagreeing about a shape they both claim to implement, and it must
 *    be loud rather than producing a watch that quietly shows nothing.
 */
class CompanionWearListenerService : WearableListenerService() {

    override fun onCreate() {
        super.onCreate()
        // Earliest hook this module owns. Does not cover install -> first launch; see
        // NotificationBridging for the two mechanisms that do.
        NotificationBridging.applyNoBridging(this)
    }

    override fun onMessageReceived(event: MessageEvent) {
        val json = event.data.toString(Charsets.UTF_8)
        when (event.path) {
            WearPaths.QUESTION -> onQuestion(decode<WatchQuestion>(event.path, json))
            WearPaths.QUESTION_OVERSIZE -> onOversize(decode(event.path, json))
            WearPaths.QUESTION_RESOLVED -> onResolved(decode(event.path, json))
            WearPaths.ANSWER_RESULT -> onAnswerResult(decode(event.path, json))
            WearPaths.CONNECTION -> QuestionStore.onConnection(decode(event.path, json))
            WearPaths.LIFECYCLE -> onLifecycle(decode(event.path, json))
            else -> Log.w(TAG, "ignoring message on unknown path ${event.path}")
        }
    }

    private fun onQuestion(question: WatchQuestion) {
        QuestionStore.onQuestion(question)
        val buzzed = QuestionNotifier.notifyQuestion(this, question)
        QuestionStore.setNotificationsBlocked(!buzzed)
    }

    private fun onOversize(info: WatchQuestionOversize) {
        QuestionStore.onOversize(info)
        val buzzed = QuestionNotifier.notifyOversize(this, info)
        QuestionStore.setNotificationsBlocked(!buzzed)
    }

    private fun onResolved(info: WatchQuestionResolved) {
        // A notification must never outlive the thing it was about (PROTOCOL.md §13.3) — cancel
        // first, unconditionally, whether or not the question is the one on screen.
        QuestionNotifier.cancel(this, info.questionId)
        QuestionStore.onResolved(info)
    }

    private fun onAnswerResult(result: WatchAnswerResult) {
        QuestionStore.onAnswerResult(result)
        if (result.status == WatchAnswerStatus.CONFIRMED) {
            QuestionNotifier.cancel(this, result.questionId)
        }
    }

    /**
     * (LIFECYCLE-ALERT) An agent finished or failed.
     *
     * Expiry is re-checked here rather than trusted from the phone. The phone dropped
     * expired pushes on arrival, but that check was made before the hop, on another
     * clock, and this watch may have been asleep when the message landed. Nothing is
     * queued for a disconnected watch — `MessageClient` drops rather than replays — so
     * lateness here is delay, not a backlog, and the wrist still decides for itself.
     *
     * [QuestionStore] is deliberately untouched. An alert that is not a question must not
     * displace one on screen, must not clear a selection the user has made, and must not
     * cancel a question notification — all three of which are what routing this through
     * the question paths would do.
     */
    private fun onLifecycle(alert: WatchLifecycleAlert) {
        if (alert.isExpired(System.currentTimeMillis())) {
            Log.i(TAG, "dropping expired lifecycle alert ${alert.eventId}")
            return
        }
        LifecycleNotifier.notify(this, alert)
    }

    private inline fun <reified T> decode(path: String, json: String): T =
        try {
            WearJson.decodeFromString<T>(json)
        } catch (e: SerializationException) {
            throw IllegalArgumentException(
                "undecodable ${T::class.java.simpleName} on $path (${json.length} chars)",
                e,
            )
        }
}

