function buildEnvelope(token: string, data: PushData): PushEnvelope {
	const envelope: PushEnvelope = {
		token,
		android: {
			priority: "high",
			ttl: `${Math.floor(PUSH_TTL_MS / 1000)}s`,
			collapse_key: data.i,
