package family.khaira.supersetcompanion.core.protocol

import family.khaira.supersetcompanion.core.CompanionConstants
import family.khaira.supersetcompanion.core.ProtocolException
import java.security.SecureRandom
import java.util.UUID

/**
 * Ids are **opaque bridge-minted handles** (PROTOCOL.md §0.1). The desktop's internal
 * identifiers — `tool_use_id`, `session_id`, transcript paths, the pty session handle —
 * are never sent to a client, and a client cannot construct a valid id it was not given.
 *
 * These validators exist so a malformed id fails at the boundary with a name attached,
 * rather than three layers later as a mysterious 400.
 */
object Ids {
    private val BASE64URL = Regex("^[A-Za-z0-9_-]+$")
    private val UUID_V4_LOWERCASE =
        Regex("^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$")

    /** A 16-byte opaque id: `deviceId`, `questionId`, `fingerprint`, `leaseId`, `projectId`, ... */
    fun requireOpaque16(value: String, field: String): String =
        requireOpaque(value, CompanionConstants.ID_CHARS_16B, field)

    /** A 12-byte opaque id: `eventId`. */
    fun requireOpaque12(value: String, field: String): String =
        requireOpaque(value, CompanionConstants.ID_CHARS_12B, field)

    /** A 32-byte opaque id: `ticket`. */
    fun requireOpaque32(value: String, field: String): String =
        requireOpaque(value, CompanionConstants.ID_CHARS_32B, field)

    fun requireOpaque(value: String, chars: Int, field: String): String {
        if (value.length != chars) {
            throw ProtocolException("$field: expected $chars characters, got ${value.length}")
        }
        if (!BASE64URL.matches(value)) {
            throw ProtocolException("$field: not base64url-unpadded")
        }
        return value
    }

    /** `requestId` is a client-minted UUIDv4, lowercase, hyphenated (§0.1). */
    fun requireRequestId(value: String, field: String = "requestId"): String {
        if (value.length != CompanionConstants.REQUEST_ID_CHARS || !UUID_V4_LOWERCASE.matches(value)) {
            throw ProtocolException("$field: must be a lowercase hyphenated UUIDv4")
        }
        return value
    }

    /**
     * Mint the idempotency key for one write attempt.
     *
     * It must stay **stable for that attempt** and must never be regenerated as part of
     * a retry — there are no write retries (§11.4), and a fresh id would defeat the
     * bridge's idempotency record even if there were.
     */
    fun newRequestId(): String = UUID.randomUUID().toString()

    /** 16 CSPRNG bytes. `SecureRandom` only — never `java.util.Random` (§15.1). */
    fun randomDeviceIdBytes(): ByteArray {
        val bytes = ByteArray(CompanionConstants.DEVICE_ID_BYTES)
        SecureRandom().nextBytes(bytes)
        return bytes
    }
}

