1	import { describe, expect, it } from "bun:test";
2	import {
3		assertPushDataSafe,
4		buildLifecyclePushData,
5		PushConfigError,
6	} from "./push";
7	
8	describe("lifecycle push v2", () => {
9		it("builds the exact content-free v2 shape", () => {
10			const data = buildLifecyclePushData({
11				alertId: "a".repeat(22),
12				workspaceId: "w".repeat(22) as never,
13				kind: "e",
14				expiresAtMs: 1_700_000_000_000,
15			});
16			expect(data).toEqual({
17				v: "2",
18				k: "e",
19				i: "a".repeat(22),
20				w: "w".repeat(22),
21				x: "1700000000000",
22			});
23			const envelope = {
24				token: "token",
25				android: {
26					priority: "high" as const,
27					ttl: "21600s",
28					collapse_key: data.i,
29				},
30				data,
31			};
32			expect(() => assertPushDataSafe(data, envelope)).not.toThrow();
33		});
34	
35		it("rejects text-like and extra values at the FCM boundary", () => {
36			const data = buildLifecyclePushData({
37				alertId: "b".repeat(22),
38				workspaceId: "w".repeat(22) as never,
39				kind: "e",
40				expiresAtMs: 1_700_000_000_000,
41			});
42			const envelope = {
43				token: "token",
44				android: {
45					priority: "high" as const,
46					ttl: "21600s",
47					collapse_key: data.i,
48				},
49				data: { ...data, i: "agent finished with error" },
50			};
51			expect(() => assertPushDataSafe(envelope.data, envelope)).toThrow(
52				PushConfigError,
53			);
54		});
55	
56		// The builder is where a malformed id must die: with no registered device
57		// `broadcast` never builds an envelope, so `assertPushDataSafe` would never
58		// see it.
59		it("rejects a malformed lifecycle alertId at the builder", () => {
60			expect(() =>
61				buildLifecyclePushData({
62					alertId: "agent finished with error",
63					workspaceId: "w".repeat(22) as never,
64					kind: "e",
65					expiresAtMs: 1_700_000_000_000,
66				}),
67			).toThrow(PushConfigError);
68			for (const alertId of ["", "a".repeat(21), "a".repeat(23), "a+b/c=d"]) {
69				expect(() =>
70					buildLifecyclePushData({
71						alertId,
72						workspaceId: "w".repeat(22) as never,
73						kind: "g",
74						expiresAtMs: 1_700_000_000_000,
75					}),
76				).toThrow(PushConfigError);
77			}
78		});
79	
80		it("rejects a malformed lifecycle workspaceId at the builder", () => {
81			for (const workspaceId of ["", "w-handle", "w".repeat(43), "feature/x"]) {
82				expect(() =>
83					buildLifecyclePushData({
84						alertId: "a".repeat(22),
85						workspaceId: workspaceId as never,
86						kind: "g",
87						expiresAtMs: 1_700_000_000_000,
88					}),
89				).toThrow(PushConfigError);
90			}
