            .setContentTitle(title)
            .setContentText(text)
            .setContentIntent(pending)
            .setCategory(NotificationCompat.CATEGORY_MESSAGE)
            .setPriority(NotificationCompat.PRIORITY_HIGH)
            .setAutoCancel(true)
            .build()

        manager.notify(notificationId(questionId), notification)
        return true
    }

    private fun ensureChannel(context: Context) {
        val manager = context.getSystemService(NotificationManager::class.java)
        if (manager.getNotificationChannel(CHANNEL_ID) != null) return
        val channel = NotificationChannel(
            CHANNEL_ID,
            "Blocked agents",
            NotificationManager.IMPORTANCE_HIGH,
        ).apply {
            description = "An agent on the desktop is waiting for an answer."
            enableVibration(true)
            // Two distinct taps: a single long buzz reads as a generic alert on the wrist.
            vibrationPattern = longArrayOf(0L, 250L, 150L, 250L)
            setShowBadge(true)
        }
        manager.createNotificationChannel(channel)
    }

    /** Stable per question so a retraction cancels exactly the notification it is about. */
    private fun notificationId(questionId: String): Int = questionId.hashCode()
