const id = (char: string) => char.repeat(22);

function setup(initiallyPresent = false) {
	let now = 1_000;
	let present = initiallyPresent;
	const sent: Array<{ kind: string; alertId: string }> = [];
	const manager = createLifecycleAlertManager({
		presence: { present: () => ({ present }) } as never,
		push: {
			sendLifecycleAlert: async (input) => {
				sent.push({ kind: input.kind, alertId: input.alertId });
			},
		},
		workspaceHandle: () => id("w") as never,
		isCuratedOff: () => false,
		logger: { info: () => {}, error: () => {} } as never,
		now: () => now,
	});
	return {
		manager,
		sent,
		setNow: (value: number) => (now = value),
		setPresent: (value: boolean) => (present = value),
	};
}

