		previousEventAtMs: null,
		...overrides,
	};
}

describe("lifecycle alerts", () => {
	it("alerts once for Start then clean Stop and rearms for the next cycle", async () => {
		const state = setup();
		state.manager.record(event());
		state.manager.record(
			event({
				outcome: "ready",
				eventType: "Stop",
				occurredAtMs: 2_000,
				previousEventType: "Start",
				previousEventAtMs: 1_000,
			}),
		);
		state.manager.record(
			event({
				outcome: "ready",
				eventType: "Stop",
				occurredAtMs: 2_100,
				previousEventType: "Stop",
				previousEventAtMs: 2_000,
			}),
		);
		await new Promise((resolve) => setTimeout(resolve, 0));
		expect(state.sent).toHaveLength(1);
		expect(state.sent[0]?.kind).toBe("g");

		state.setNow(3_000);
		state.manager.record(event({ occurredAtMs: 3_000 }));
		state.manager.record(
			event({
				outcome: "ready",
				eventType: "Stop",
				occurredAtMs: 4_000,
				previousEventType: "Start",
				previousEventAtMs: 3_000,
			}),
		);
		await new Promise((resolve) => setTimeout(resolve, 0));
		expect(state.sent).toHaveLength(2);
		expect(state.sent[0]?.alertId).not.toBe(state.sent[1]?.alertId);
		// PROTOCOL.md §0.1: 16 digest bytes, base64url, 22 chars.
		for (const row of state.sent) {
			const bytes = Buffer.from(row.alertId, "base64url");
			expect(bytes).toHaveLength(16);
			expect(bytes.toString("base64url")).toBe(row.alertId);
		}
		state.manager.stop();
	});

	it("turns a deferred failure into error, never ready", async () => {
		const state = setup();
		state.manager.record(event());
		state.manager.record(
			event({ outcome: "hold", eventType: "SubagentActive" }),
		);
		state.manager.record(
			event({
				outcome: "failed",
				eventType: "Failed",
				occurredAtMs: 2_000,
				previousEventType: "SubagentActive",
				previousEventAtMs: 1_500,
			}),
		);
		await new Promise((resolve) => setTimeout(resolve, 0));
		expect(state.sent.map((row) => row.kind)).toEqual(["e"]);
		state.manager.stop();
	});

	it("holds while present and releases after presence changes", async () => {
		const state = setup(true);
		state.manager.record(event());
		state.manager.record(
			event({
				outcome: "ready",
				eventType: "Stop",
				occurredAtMs: 2_000,
				previousEventType: "Start",
				previousEventAtMs: 1_000,
			}),
		);
		await new Promise((resolve) => setTimeout(resolve, 0));
		expect(state.sent).toEqual([]);
		state.setPresent(false);
		await new Promise((resolve) => setTimeout(resolve, 2_100));
		expect(state.sent).toHaveLength(1);
		state.manager.stop();
	});
});

import { createHash } from "node:crypto";
import type { CompanionLifecycleEvent } from "../trpc/router/notifications";
import type { BridgeLogger } from "./http";
import type { PresenceStore } from "./presence";
import type { PushSender } from "./push";
import type { HostDbReader } from "./read-api";
import { workspaceSidebarVerdict } from "./sidebar-filter";
import type { WorkspaceId } from "./types";

const ALERT_TTL_MS = 6 * 60 * 60 * 1000;
const SWEEP_MS = 2_000;
const MAX_STATE_ENTRIES = 512;

type LifecycleAlertKind = "g" | "e";

interface HeldAlert {
	alertId: string;
	kind: LifecycleAlertKind;
	hostWorkspaceId: string;
	workspaceHandle: WorkspaceId;
	expiresAtMs: number;
	state: "held" | "sent";
}

export interface LifecycleAlertManager {
	record(input: CompanionLifecycleEvent): void;
	stop(): void;
}

export function isLifecycleWorkspaceCuratedOff(input: {
	db: HostDbReader;
	organizationId: string;
	hostWorkspaceId: string;
	nowMs: number;
}): boolean {
	return (
		workspaceSidebarVerdict({
			snapshot: input.db.readSidebarMirror(),
			nowMs: input.nowMs,
			organizationId: input.organizationId,
			workspace: input.db.findWorkspace(input.hostWorkspaceId),
		}) !== "show"
	);
}

export interface LifecycleAlertManagerDeps {
	presence: PresenceStore;
	push: Pick<PushSender, "sendLifecycleAlert">;
	workspaceHandle(hostWorkspaceId: string): WorkspaceId;
	isCuratedOff(hostWorkspaceId: string): boolean;
	logger: BridgeLogger;
	now?: () => number;
}

function lifecycleAlertId(input: {
	hostTerminalId: string;
	armedAtMs: number;
	kind: LifecycleAlertKind;
}): string {
	// PROTOCOL.md §0.1: first 16 digest bytes, base64url encoded (22 chars).
	return createHash("sha256")
		.update("sc/v2 lifecycle alert\0", "utf8")
		.update(input.kind, "utf8")
		.update("\0", "utf8")
		.update(input.hostTerminalId, "utf8")
		.update("\0", "utf8")
		.update(String(input.armedAtMs), "utf8")
		.digest()
		.subarray(0, 16)
		.toString("base64url");
}

/**
 * Lifecycle delivery state is intentionally process-local. The validated hook
 * stream and the host DB remain the lifecycle source of truth; this bounded map
 * only holds informational alerts while presence or sidebar curation delays
 * delivery. A host-service restart can lose an unsent held alert. Durable
 * delivery would require an explicitly approved database schema change.
 */
export function createLifecycleAlertManager(
	deps: LifecycleAlertManagerDeps,
): LifecycleAlertManager {
	const now = deps.now ?? (() => Date.now());
	const alerts = new Map<string, HeldAlert>();
	let stopped = false;
	let timer: NodeJS.Timeout | null = null;

	function trimOldest<T>(map: Map<string, T>): void {
		while (map.size > MAX_STATE_ENTRIES) {
			const oldest = map.keys().next();
			if (oldest.done) return;
			map.delete(oldest.value);
		}
	}

	function prune(nowMs: number): void {
		for (const [alertId, alert] of alerts) {
			if (alert.expiresAtMs <= nowMs) alerts.delete(alertId);
		}
		trimOldest(alerts);
	}

	function heldAlerts(): HeldAlert[] {
		return [...alerts.values()].filter((alert) => alert.state === "held");
	}

	function hasHeldAlert(): boolean {
		for (const alert of alerts.values()) {
			if (alert.state === "held") return true;
		}
		return false;
	}

	function scheduleSweep(): void {
		if (timer !== null || stopped || !hasHeldAlert()) return;
		timer = setTimeout(() => {
			timer = null;
			void sweep();
		}, SWEEP_MS);
		timer.unref?.();
	}

	async function send(alert: HeldAlert): Promise<void> {
		if (stopped) return;
		const nowMs = now();
		if (alert.expiresAtMs <= nowMs) {
			alerts.delete(alert.alertId);
			return;
		}
		if (deps.presence.present(nowMs).present) return;
		if (deps.isCuratedOff(alert.hostWorkspaceId)) return;
		alerts.set(alert.alertId, { ...alert, state: "sent" });
		try {
			await deps.push.sendLifecycleAlert({
				alertId: alert.alertId,
				workspaceId: alert.workspaceHandle,
				kind: alert.kind,
				expiresAtMs: alert.expiresAtMs,
			});
		} catch (error) {
			deps.logger.error("could not send lifecycle alert", {
				alertId: alert.alertId,
				kind: alert.kind,
				error,
			});
		}
	}

	async function sweep(): Promise<void> {
		prune(now());
		for (const alert of heldAlerts()) await send(alert);
		scheduleSweep();
	}

	function mint(
		input: CompanionLifecycleEvent,
		cycleStartedAtMs: number,
		kind: LifecycleAlertKind,
	): void {
		const alertId = lifecycleAlertId({
			hostTerminalId: input.hostTerminalId,
			armedAtMs: cycleStartedAtMs,
			kind,
		});
		if (alerts.has(alertId)) return;
		const nowMs = now();
		const alert: HeldAlert = {
			alertId,
			kind,
			hostWorkspaceId: input.hostWorkspaceId,
			workspaceHandle: deps.workspaceHandle(input.hostWorkspaceId),
			expiresAtMs: input.occurredAtMs + ALERT_TTL_MS,
			state: "held",
		};
		alerts.set(alertId, alert);
		prune(nowMs);
		void send(alert);
		scheduleSweep();
	}

	return {
		record(input) {
			if (stopped) return;
			prune(now());
			if (input.outcome !== "ready" && input.outcome !== "failed") return;

			// DB source of truth: the router captures these fields from the persisted
			// terminal binding before recordEvent replaces them. Only a terminal event
			// following real work can produce an alert. Repeated Stop/Failed events see
			// the previous terminal event and are therefore silent. PermissionRequest is
			// intentionally absent: answering a prompt and ending the turn must not be
			// reported as fresh completed work.
			if (
				input.previousEventAtMs === null ||
				(input.previousEventType !== "Start" &&
					input.previousEventType !== "SubagentActive" &&
					input.previousEventType !== "BackgroundRunning")
			)
				return;

			mint(
				input,
				input.previousEventAtMs,
				input.outcome === "failed" ? "e" : "g",
			);
		},
		stop() {
			stopped = true;
			if (timer !== null) clearTimeout(timer);
			timer = null;
			alerts.clear();
		},
	};
}

import { describe, expect, it } from "bun:test";
import {
	assertPushDataSafe,
	buildLifecyclePushData,
	PushConfigError,
} from "./push";

describe("lifecycle push v2", () => {
	it("builds the exact content-free v2 shape", () => {
		const data = buildLifecyclePushData({
			alertId: "a".repeat(22),
			workspaceId: "w".repeat(22) as never,
			kind: "e",
			expiresAtMs: 1_700_000_000_000,
		});
		expect(data).toEqual({
			v: "2",
			k: "e",
			i: "a".repeat(22),
			w: "w".repeat(22),
			x: "1700000000000",
		});
		const envelope = {
			token: "token",
			android: {
				priority: "high" as const,
				ttl: "21600s",
				collapse_key: data.i,
			},
			data,
		};
		expect(() => assertPushDataSafe(data, envelope)).not.toThrow();
	});

	it("rejects text-like and extra values at the FCM boundary", () => {
		const data = buildLifecyclePushData({
			alertId: "b".repeat(22),
			workspaceId: "w".repeat(22) as never,
			kind: "e",
			expiresAtMs: 1_700_000_000_000,
		});
		const leaked = { ...data, i: "agent finished with error" };
		const envelope = {
			token: "token",
			android: {
				priority: "high" as const,
				ttl: "21600s",
				collapse_key: leaked.i,
			},
			data: leaked,
		};
		expect(() => assertPushDataSafe(leaked, envelope)).toThrow(PushConfigError);
	});

	// The builder is where a malformed id must die: with no registered device
	// `broadcast` never builds an envelope, so `assertPushDataSafe` would never
	// see it.
	it("rejects a malformed lifecycle alertId at the builder", () => {
		expect(() =>
			buildLifecyclePushData({
				alertId: "agent finished with error",
				workspaceId: "w".repeat(22) as never,
				kind: "e",
				expiresAtMs: 1_700_000_000_000,
			}),
		).toThrow(PushConfigError);
		for (const alertId of ["", "a".repeat(21), "a".repeat(23), "a+b/c=d"]) {
			expect(() =>
				buildLifecyclePushData({
					alertId,
					workspaceId: "w".repeat(22) as never,
					kind: "g",
					expiresAtMs: 1_700_000_000_000,
				}),
			).toThrow(PushConfigError);
		}
	});

	it("rejects a malformed lifecycle workspaceId at the builder", () => {
		for (const workspaceId of ["", "w-handle", "w".repeat(43), "feature/x"]) {
			expect(() =>
				buildLifecyclePushData({
					alertId: "a".repeat(22),
					workspaceId: workspaceId as never,
					kind: "g",
					expiresAtMs: 1_700_000_000_000,
				}),
			).toThrow(PushConfigError);
		}
	});

	it("never echoes the rejected id in the error message", () => {
		expect(() =>
			buildLifecyclePushData({
				alertId: "agent finished with error",
				workspaceId: "w".repeat(22) as never,
				kind: "e",
				expiresAtMs: 1_700_000_000_000,
			}),
		).toThrow(/^(?!.*agent finished with error).*$/);
	});
});

